// PORT-NOTE(seam-threading): faithful skeleton signature carries no &Engine/&mut GameWorld, but `level`/`g_entities` globals and `trap_Trace` are needed — how is state threaded in?
/// Raven `WP_LobFire`.
///
/// Source: `oracle/codemp/game/g_weapon.c:2082-2226`
pub fn WP_LobFire(
    ctx: GameContext<'_>,
    self_: EntityId,
    start: vec3_t,
    target: vec3_t,
    mins: vec3_t,
    maxs: vec3_t,
    clipmask: c_int,
    velocity: &mut vec3_t,
    tracePath: qboolean,
    ignoreEntNum: c_int,
    enemyNum: c_int,
    minSpeed: f32,
    maxSpeed: f32,
    idealSpeed: f32,
    mustHit: qboolean,
) -> qboolean {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let self_: *mut gentity_t = ctx.entity_mut(self_);
    // for the galak mech NPC
    unsafe {
        let mut idealSpeed = idealSpeed;
        let mut minSpeed = minSpeed;
        let mut maxSpeed = maxSpeed;
        let speedInc: f32 = 100.0;
        let mut shotSpeed: f32;
        let mut bestImpactDist: f32 = Q3_INFINITE as f32;
        let mut targetDir: vec3_t = [0.0; 3];
        let mut shotVel: vec3_t = [0.0; 3];
        let mut failCase: vec3_t = [0.0; 3];
        let mut trace: trace_t = std::mem::zeroed();
        let mut tr: trajectory_t = std::mem::zeroed();
        let mut blocked: qboolean;
        let timeStep: c_int = 500;
        let mut hitCount: c_int = 0;
        let maxHits: c_int = 7;
        let mut lastPos: vec3_t;
        let mut testPos: vec3_t = [0.0; 3];

        if idealSpeed == 0.0 {
            idealSpeed = 300.0;
        } else if idealSpeed < speedInc {
            idealSpeed = speedInc;
        }
        shotSpeed = idealSpeed;
        let skipNum: c_int = ((idealSpeed - speedInc) / speedInc) as c_int;
        if minSpeed == 0.0 {
            minSpeed = 100.0;
        }
        if maxSpeed == 0.0 {
            maxSpeed = 900.0;
        }
        let _ = (minSpeed, maxSpeed); // Raven never reads these back after clamping shotSpeed via skipNum/speedInc

        while hitCount < maxHits {
            crate::q_math::_VectorSubtract(target, start, &mut targetDir);
            let targetDist = crate::q_math::VectorNormalize(&mut targetDir);

            crate::q_math::_VectorScale(targetDir, shotSpeed, &mut shotVel);
            let mut travelTime = targetDist / shotSpeed;
            // C's `0.5` is a double literal, so the whole `travelTime * 0.5 *
            // g_gravity.value` product runs in f64 and narrows at the `+=`.
            shotVel[2] +=
                (travelTime as f64 * 0.5 * (*ctx.world).cvars.g_gravity.value as f64) as f32;

            if hitCount == 0 {
                // save the first (ideal) one as the failCase (fallback value)
                if mustHit == qfalse {
                    // default is fine as a return value
                    failCase = shotVel;
                }
            }

            if tracePath != qfalse {
                // do a rough trace of the path
                blocked = qfalse;

                tr.trBase = start;
                tr.trDelta = shotVel;
                tr.trType = TR_GRAVITY;
                tr.trTime = (*ctx.world).level.time;
                travelTime *= 1000.0;
                lastPos = start;

                let mut elapsedTime: c_int = timeStep;
                while (elapsedTime as f32) < travelTime.floor() + timeStep as f32 {
                    if elapsedTime as f32 > travelTime {
                        // cap it
                        elapsedTime = travelTime.floor() as c_int;
                    }
                    crate::bg_misc::BG_EvaluateTrajectory(
                        &tr,
                        (*ctx.world).level.time + elapsedTime,
                        &mut testPos,
                    );
                    trap::Trace(
                        ctx.engine,
                        mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                            &mut trace,
                            &lastPos as *const vec3_t,
                            &mins as *const vec3_t,
                            &maxs as *const vec3_t,
                            &testPos as *const vec3_t,
                            ignoreEntNum,
                            clipmask,
                        ),
                    );

                    if trace.allsolid != 0 || trace.startsolid != 0 {
                        blocked = qtrue;
                        break;
                    }
                    if trace.fraction < 1.0 {
                        // hit something
                        if trace.entityNum as c_int == enemyNum {
                            // hit the enemy, that's perfect!
                            break;
                        } else if trace.plane.normal[2] > 0.7
                            && crate::q_math::DistanceSquared(trace.endpos, target) < 4096.0
                        {
                            // hit within 64 of desired location, should be okay
                            break;
                        } else {
                            // FIXME: maybe find the extents of this brush and go above or below it on next try somehow?
                            let impactDist = crate::q_math::DistanceSquared(trace.endpos, target);
                            if impactDist < bestImpactDist {
                                bestImpactDist = impactDist;
                                failCase = shotVel;
                            }
                            blocked = qtrue;
                            // see if we should store this as the failCase
                            if (trace.entityNum as c_int) < ENTITYNUM_WORLD as c_int {
                                // hit an ent
                                let traceEnt = &mut (*ctx.world).g_entities
                                    [trace.entityNum as usize]
                                    as *mut gentity_t;
                                if !traceEnt.is_null()
                                    && (*traceEnt).takedamage != 0
                                    && crate::g_team::OnSameTeam(ctx, self_, traceEnt) == qfalse
                                {
                                    // hit something breakable, so that's okay
                                    // we haven't found a clear shot yet so use this as the failcase
                                    failCase = shotVel;
                                }
                            }
                            break;
                        }
                    }
                    if elapsedTime == travelTime.floor() as c_int {
                        // reached end, all clear
                        break;
                    } else {
                        // all clear, try next slice
                        lastPos = testPos;
                    }
                    elapsedTime += timeStep;
                }
                if blocked != qfalse {
                    // hit something, adjust speed (which will change arc)
                    hitCount += 1;
                    shotSpeed = idealSpeed + ((hitCount - skipNum) as f32 * speedInc); // from min to max (skipping ideal)
                    if hitCount >= skipNum {
                        // skip ideal since that was the first value we tested
                        shotSpeed += speedInc;
                    }
                } else {
                    // made it!
                    break;
                }
            } else {
                // no need to check the path, go with first calc
                break;
            }
        }

        if hitCount >= maxHits {
            // NOTE: worst case scenario, use the one that impacted closest to the target (or just use the first try...?)
            *velocity = failCase;
            return qfalse;
        }
        *velocity = shotVel;
        qtrue
    }
    // PORT-NOTE(out-param-vec3): `velocity` is a vec3_t out-param per the
    // settled vec3 rule (docs/porting/rosetta.md: outputs are `&mut`); Raven
    // copies `failCase` (worst case) or `shotVel` (success) back through it.
}

// PORT-NOTE(seam-threading): faithful skeleton signature carries no &Engine/&mut GameWorld, but `level.time` is needed — how is state threaded in?
/// Raven `laserTrapExplode`.
///
/// Source: `oracle/codemp/game/g_weapon.c:2244-2280`
pub fn laserTrapExplode(ctx: GameContext<'_>, self_: EntityId) {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let self_: *mut gentity_t = ctx.entity_mut(self_);
    unsafe {
        let mut v: vec3_t;
        (*self_).takedamage = qfalse;

        if let Some(activator_id) = (*self_).activator {
            let activator = &mut (*ctx.world).g_entities[activator_id.index()] as *mut gentity_t;
            crate::g_combat::G_RadiusDamage(
                ctx,
                (*self_).r.currentOrigin,
                ctx.entity_id_of(activator),
                (*self_).splashDamage as f32,
                ((*self_).splashRadius) as f32,
                ctx.entity_id_of(self_),
                ctx.entity_id_of(self_),
                MOD_TRIP_MINE_SPLASH as c_int, /* MOD_LT_SPLASH */
            );
        }

        if (*self_).s.weapon != WP_FLECHETTE {
            crate::g_utils::G_AddEvent(self_, EV_MISSILE_MISS as c_int, 0);
        }

        v = (*self_).s.pos.trDelta;
        // Explode outward from the surface

        if (*self_).s.time == -2 {
            v = [0.0, 0.0, 0.0];
        }

        if (*self_).s.weapon == WP_FLECHETTE {
            crate::g_utils::G_PlayEffect(
                (EFFECT_EXPLOSION_FLECHETTE) as i32,
                (*self_).r.currentOrigin,
                v,
            );
        } else {
            crate::g_utils::G_PlayEffect(
                (EFFECT_EXPLOSION_TRIPMINE) as i32,
                (*self_).r.currentOrigin,
                v,
            );
        }

        (*self_).think = Some(EntThink::G_FreeEntity).into();
        (*self_).nextthink = (*ctx.world).level.time;
    }
}

// PORT-NOTE(seam-threading): faithful skeleton signature carries no &Engine/&mut GameWorld, but `level.time` is needed — how is state threaded in?
/// Raven `laserTrapDelayedExplode`.
