// PORT-NOTE(seam-threading): faithful skeleton signature carries no &Engine/&mut GameWorld, but `level`/`g_entities` globals and the file-static `forward`/`vright`/`up`/`muzzle` globals are needed — how is state threaded in?
/// Raven `WP_DropDetPack`.
///
/// Source: `oracle/codemp/game/g_weapon.c:2880-2964`
pub fn WP_DropDetPack(ctx: GameContext<'_>, ent: Option<EntityId>, alt_fire: qboolean) {
    // STAGE-1: Option param (body null-checks ent), raw re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t =
        unsafe { crate::ent_id::resolve(ctx.world().g_entities.as_mut_ptr(), ent) };
    unsafe {
        if ent.is_null() || (*ent).client.is_null() {
            return;
        }

        let fofs_classname = core::mem::offset_of!(gentity_t, classname) as c_int;
        let mut foundDetPacks: [c_int; MAX_GENTITIES] = [ENTITYNUM_NONE as c_int; MAX_GENTITIES];
        let mut trapcount: c_int = 0;

        // limit to 10 placed at any one time
        // see how many there are now
        let mut found: *mut gentity_t = std::ptr::null_mut();
        loop {
            found = crate::g_utils::G_Find(ctx, found, fofs_classname, c"detpack".as_ptr());
            if found.is_null() {
                break;
            }
            if (*found).parent != Some(ent_id((*ctx.world).g_entities.as_mut_ptr(), ent)) {
                continue;
            }
            foundDetPacks[trapcount as usize] = (*found).s.number;
            trapcount += 1;
        }
        // now remove first ones we find until there are only 9 left
        found = std::ptr::null_mut();
        let trapcount_org = trapcount;
        let mut lowestTimeStamp = (*ctx.world).level.time;
        while trapcount > 9 {
            let mut removeMe: c_int = -1;
            for i in 0..trapcount_org {
                if foundDetPacks[i as usize] == ENTITYNUM_NONE as c_int {
                    continue;
                }
                found = &mut (*ctx.world).g_entities[foundDetPacks[i as usize] as usize]
                    as *mut gentity_t;
                if (*found).setTime < lowestTimeStamp {
                    removeMe = i;
                    lowestTimeStamp = (*found).setTime;
                }
            }
            if removeMe != -1 {
                // remove it... or blow it?
                if CheatsOn(ctx) == qfalse {
                    // Let them have unlimited if cheats are enabled
                    let victim = &mut (*ctx.world).g_entities
                        [foundDetPacks[removeMe as usize] as usize]
                        as *mut gentity_t;
                    crate::g_utils::G_FreeEntity(ctx, victim);
                }
                foundDetPacks[removeMe as usize] = ENTITYNUM_NONE as c_int;
                trapcount -= 1;
            } else {
                break;
            }
        }

        if alt_fire != qfalse {
            BlowDetpacks(ctx, ctx.entity_id_of(ent).unwrap());
        } else {
            crate::q_math::AngleVectors(
                (*((*ent).client as *mut gclient_t)).ps.viewangles,
                Some(&mut (*ctx.world).globals.forward),
                Some(&mut (*ctx.world).globals.vright),
                Some(&mut (*ctx.world).globals.up),
            );

            CalcMuzzlePoint(
                ctx,
                ctx.entity_id_of(ent).unwrap(),
                (*ctx.world).globals.forward,
                (*ctx.world).globals.vright,
                (*ctx.world).globals.up,
                &mut (*ctx.world).globals.muzzle,
            );

            crate::q_math::VectorNormalize(&mut (*ctx.world).globals.forward);
            crate::q_math::_VectorMA(
                (*ctx.world).globals.muzzle,
                -4.0,
                (*ctx.world).globals.forward,
                &mut (*ctx.world).globals.muzzle,
            );
            drop_charge(
                ctx,
                ctx.entity_id_of(ent).unwrap(),
                (*ctx.world).globals.muzzle,
                (*ctx.world).globals.forward,
            );

            (*((*ent).client as *mut gclient_t)).ps.hasDetPackPlanted = qtrue;
        }
    }
}

// PORT-NOTE(seam-threading): faithful skeleton signature carries no &Engine/&mut GameWorld, but `level`/`g_entities` globals, the file-static `forward`/`muzzle` globals, cvars, and `trap_G2Trace`/`trap_Trace` are needed — how is state threaded in?
/// Raven `WP_FireConcussionAlt`.
///
/// Source: `oracle/codemp/game/g_weapon.c:2967-3229`
pub fn WP_FireConcussionAlt(ctx: GameContext<'_>, ent: EntityId) {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t = ctx.entity_mut(ent);
    // a rail-gun-like beam
    unsafe {
        let damage: c_int = CONC_ALT_DAMAGE;
        let traces: c_int = DISRUPTOR_ALT_TRACES;
        let mut render_impact = qtrue;
        let mut start: vec3_t;
        let mut end: vec3_t = [0.0; 3];
        let mut muzzle2 = (*ctx.world).globals.muzzle;
        let mut tr: trace_t = std::mem::zeroed();
        let mut traceEnt: *mut gentity_t;
        let mut tent: *mut gentity_t;
        let shotRange: f32 = 8192.0;
        let mut hitDodged = qfalse;
        let mut shot_mins: vec3_t = [-1.0, -1.0, -1.0];
        let mut shot_maxs: vec3_t = [1.0, 1.0, 1.0];

        // Shove us backwards for half a second
        crate::q_math::_VectorMA(
            (*((*ent).client as *mut gclient_t)).ps.velocity,
            -200.0,
            (*ctx.world).globals.forward,
            &mut (*((*ent).client as *mut gclient_t)).ps.velocity,
        );
        (*((*ent).client as *mut gclient_t)).ps.groundEntityNum = ENTITYNUM_NONE as c_int;
        if (*((*ent).client as *mut gclient_t)).ps.pm_flags & PMF_DUCKED != 0 {
            // hunkered down
            (*((*ent).client as *mut gclient_t)).ps.pm_time = 100;
        } else {
            (*((*ent).client as *mut gclient_t)).ps.pm_time = 250;
        }

        muzzle2 = (*ctx.world).globals.muzzle; // making a backup copy

        start = (*ctx.world).globals.muzzle;
        start = W_TraceSetStart(
            ctx,
            ctx.entity_id_of(ent).unwrap(),
            start,
            [0.0; 3],
            [0.0; 3],
        );

        let mut skip: c_int = (*ent).s.number;

        for _i in 0..traces {
            crate::q_math::_VectorMA(start, shotRange, (*ctx.world).globals.forward, &mut end);

            if (*ctx.world).cvars.d_projectileGhoul2Collision.integer != 0 {
                trap::G2Trace(
                    ctx.engine,
                    mp_abi::game::syscalls::G_G2TRACE::GG2TraceArgs::new(
                        &mut tr,
                        &start as *const vec3_t,
                        &shot_mins as *const vec3_t,
                        &shot_maxs as *const vec3_t,
                        &end as *const vec3_t,
                        skip,
                        MASK_SHOT,
                        G2TRFLAG_DOGHOULTRACE | G2TRFLAG_GETSURFINDEX | G2TRFLAG_HITCORPSES,
                        (*ctx.world).cvars.g_g2TraceLod.integer,
                    ),
                );
            } else {
                trap::Trace(
                    ctx.engine,
                    mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                        &mut tr,
                        &start as *const vec3_t,
                        &shot_mins as *const vec3_t,
                        &shot_maxs as *const vec3_t,
                        &end as *const vec3_t,
                        skip,
                        MASK_SHOT,
                    ),
                );
            }

            traceEnt = &mut (*ctx.world).g_entities[tr.entityNum as usize] as *mut gentity_t;

            if (*ctx.world).cvars.d_projectileGhoul2Collision.integer != 0
                && (*traceEnt).inuse != 0
                && !(*traceEnt).client.is_null()
            {
                // g2 collision checks -rww
                if (*traceEnt).inuse != 0
                    && !(*traceEnt).client.is_null()
                    && !(*traceEnt).ghoul2.is_null()
                {
                    (*((*traceEnt).client as *mut gclient_t)).g2LastSurfaceHit = tr.surfaceFlags;
                    (*((*traceEnt).client as *mut gclient_t)).g2LastSurfaceTime =
                        (*ctx.world).level.time;
                }
                if !(*traceEnt).ghoul2.is_null() {
                    tr.surfaceFlags = 0;
                }
            }
            if (tr.surfaceFlags & SURF_NOIMPACT) != 0 {
                render_impact = qfalse;
            }

            if tr.entityNum == (*ent).s.number as i16 {
                // should never happen, but basically we don't want to consider a
                // hit to ourselves? Get ready for an attempt to trace through
                // another person
                muzzle2 = tr.endpos;
                start = tr.endpos;
                skip = tr.entityNum as c_int;
                continue;
            }

            if tr.fraction >= 1.0 {
                // draw the beam but don't do anything else
                break;
            }

            if (*traceEnt).s.weapon == WP_SABER {
                // FIXME: need a more reliable way to know we hit a jedi?
                hitDodged = crate::w_force::Jedi_DodgeEvasion(ctx, traceEnt, ent, &mut tr, HL_NONE);
                // acts like we didn't even hit him
            }
            if hitDodged == qfalse {
                if render_impact != qfalse {
                    if (tr.entityNum < ENTITYNUM_WORLD as i16 && (*traceEnt).takedamage != 0)
                        || Q_stricmp((*traceEnt).classname, c"misc_model_breakable".as_ptr()) == 0
                        || (*traceEnt).s.eType == (ET_MOVER) as i32
                    {
                        // Create a simple impact type mark that doesn't last long in the world
                        if !(*traceEnt).client.is_null()
                            && LogAccuracyHit(
                                ctx,
                                ctx.entity_id_of(traceEnt).unwrap(),
                                ctx.entity_id_of(ent),
                            ) != qfalse
                        {
                            // NOTE: hitting multiple ents can still get you over 100% accuracy
                            (*((*ent).client as *mut gclient_t)).accuracy_hits += 1;
                        }

                        let noKnockBack = (*traceEnt).flags & FL_NO_KNOCKBACK; // will be set if they die, I want to know if it was on *before* they died
                        if !(*traceEnt).client.is_null()
                            && (*((*traceEnt).client as *mut gclient_t)).NPC_class
                                == CLASS_GALAKMECH
                        {
                            // hehe
                            crate::g_combat::G_Damage(
                                ctx,
                                ctx.entity_id_of(traceEnt),
                                ctx.entity_id_of(ent),
                                ctx.entity_id_of(ent),
                                Some(&mut (*ctx.world).globals.forward),
                                tr.endpos,
                                10,
                                DAMAGE_NO_KNOCKBACK | DAMAGE_NO_HIT_LOC,
                                MOD_CONC_ALT as c_int,
                            );
                            break;
                        }
                        crate::g_combat::G_Damage(
                            ctx,
                            ctx.entity_id_of(traceEnt),
                            ctx.entity_id_of(ent),
                            ctx.entity_id_of(ent),
                            Some(&mut (*ctx.world).globals.forward),
                            tr.endpos,
                            damage,
                            DAMAGE_NO_KNOCKBACK | DAMAGE_NO_HIT_LOC,
                            MOD_CONC_ALT as c_int,
                        );

                        // do knockback and knockdown manually
                        if !(*traceEnt).client.is_null() {
                            // only if we hit a client
                            let mut pushDir: vec3_t = (*ctx.world).globals.forward;
                            if pushDir[2] < 0.2 {
                                pushDir[2] = 0.2;
                            } // hmm, re-normalize?  nah...

                            if (*traceEnt).health > 0 {
                                // alive
                                if noKnockBack == 0
                                    && (*traceEnt).localAnimIndex == 0
                                    && (*((*traceEnt).client as *mut gclient_t)).ps.forceHandExtend
                                        != (HANDEXTEND_KNOCKDOWN) as i32
                                    && crate::bg_pmove::BG_KnockDownable(
                                        &mut (*((*traceEnt).client as *mut gclient_t)).ps,
                                    ) != qfalse
                                {
                                    // knock-downable
                                    let mut plPDif: vec3_t = [0.0; 3];
                                    let mut pStr: f32;

                                    // cap it and stuff, base the strength and whether or not we
                                    // can knockdown on the distance from the shooter to the target
                                    crate::q_math::_VectorSubtract(
                                        (*((*traceEnt).client as *mut gclient_t)).ps.origin,
                                        (*((*ent).client as *mut gclient_t)).ps.origin,
                                        &mut plPDif,
                                    );
                                    pStr = 500.0 - crate::q_math::VectorLength(plPDif);
                                    if pStr < 150.0 {
                                        pStr = 150.0;
                                    }
                                    if pStr > 200.0 {
                                        (*((*traceEnt).client as *mut gclient_t))
                                            .ps
                                            .forceHandExtend = (HANDEXTEND_KNOCKDOWN) as i32;
                                        (*((*traceEnt).client as *mut gclient_t))
                                            .ps
                                            .forceHandExtendTime = (*ctx.world).level.time + 1100;
                                        (*((*traceEnt).client as *mut gclient_t))
                                            .ps
                                            .forceDodgeAnim = 0; // this toggles between 1 and 0, when it's 1 we should play the get up anim
                                    }
                                    (*((*traceEnt).client as *mut gclient_t)).ps.otherKiller =
                                        (*ent).s.number;
                                    (*((*traceEnt).client as *mut gclient_t)).ps.otherKillerTime =
                                        (*ctx.world).level.time + 5000;
                                    (*((*traceEnt).client as *mut gclient_t))
                                        .ps
                                        .otherKillerDebounceTime = (*ctx.world).level.time + 100;
                                    (*((*traceEnt).client as *mut gclient_t)).otherKillerMOD =
                                        MOD_UNKNOWN as c_int;
                                    (*((*traceEnt).client as *mut gclient_t))
                                        .otherKillerVehWeapon = 0;
                                    (*((*traceEnt).client as *mut gclient_t))
                                        .otherKillerWeaponType = WP_NONE;

                                    (*((*traceEnt).client as *mut gclient_t)).ps.velocity[0] +=
                                        pushDir[0] * pStr;
                                    (*((*traceEnt).client as *mut gclient_t)).ps.velocity[1] +=
                                        pushDir[1] * pStr;
                                    (*((*traceEnt).client as *mut gclient_t)).ps.velocity[2] = pStr;
                                }
                            }
                        }

                        if (*traceEnt).s.eType == (ET_MOVER) as i32 {
                            // stop the traces on any mover
                            break;
                        }
                    } else {
                        // we only make this mark on things that can't break or move
                        break; // hit solid, but doesn't take damage, so stop the shot...we _could_ allow it to shoot through walls, might be cool?
                    }
                } else {
                    // not rendering impact, must be a skybox or other similar thing?
                    break; // don't try anymore traces
                }
            }
            // Get ready for an attempt to trace through another person
            muzzle2 = tr.endpos;
            start = tr.endpos;
            skip = tr.entityNum as c_int;
            hitDodged = qfalse;
        }
        // just draw one beam all the way to the end

        // now go along the trail and make sight events
        let mut dir: vec3_t = [0.0; 3];
        crate::q_math::_VectorSubtract(tr.endpos, (*ctx.world).globals.muzzle, &mut dir);

        // let's pack all this junk into a single tempent, and send it off.
        tent = crate::g_utils::G_TempEntity(ctx, tr.endpos, (EV_CONC_ALT_IMPACT) as i32);
        (*tent).s.eventParm = crate::q_math::DirToByte(tr.plane.normal);
        (*tent).s.owner = (*ent).s.number;
        (*tent).s.angles = dir;
        (*tent).s.origin2 = (*ctx.world).globals.muzzle;
        (*tent).s.angles2 = (*ctx.world).globals.forward;
    }
}

// PORT-NOTE(seam-threading): faithful skeleton signature carries no &Engine/&mut GameWorld, but `level.time` and the file-static `forward`/`muzzle` globals are needed — how is state threaded in?
/// Raven `WP_FireConcussion`.
///
/// Source: `oracle/codemp/game/g_weapon.c:3232-3276`
pub fn WP_FireConcussion(ctx: GameContext<'_>, ent: EntityId) {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t = ctx.entity_mut(ent);
    // a fast rocket-like projectile
    unsafe {
        let damage: c_int = CONC_DAMAGE;
        let vel: f32 = CONC_VELOCITY as f32;

        let mut start: vec3_t = (*ctx.world).globals.muzzle;
        start = W_TraceSetStart(
            ctx,
            ctx.entity_id_of(ent).unwrap(),
            start,
            [0.0; 3],
            [0.0; 3],
        ); // make sure our start point isn't on the other side of a wall

        let missile = crate::g_missile::CreateMissile(
            ctx,
            start,
            (*ctx.world).globals.forward,
            vel,
            10000,
            ctx.entity_id_of(ent).unwrap(),
            qfalse,
        );

        (*missile).classname = c"conc_proj".as_ptr() as *mut c_char;
        (*missile).s.weapon = WP_CONCUSSION;
        (*missile).mass = (10) as f32;

        // Make it easier to hit things
        (*missile).r.maxs = [
            (ROCKET_SIZE) as f32,
            (ROCKET_SIZE) as f32,
            (ROCKET_SIZE) as f32,
        ];
        for i in 0..3 {
            (*missile).r.mins[i] = -(*missile).r.maxs[i];
        }

        (*missile).damage = damage;
        (*missile).dflags = DAMAGE_EXTRA_KNOCKBACK;

        (*missile).methodOfDeath = MOD_CONC as c_int;
        (*missile).splashMethodOfDeath = MOD_CONC as c_int;

        (*missile).clipmask = MASK_SHOT | CONTENTS_LIGHTSABER;
        (*missile).splashDamage = CONC_SPLASH_DAMAGE;
        (*missile).splashRadius = CONC_SPLASH_RADIUS;

        // we don't want it to ever bounce
        (*missile).bounceCount = 0;
    }
}

// PORT-NOTE(seam-threading): faithful skeleton signature carries no &Engine/&mut GameWorld, but `level`/`g_entities` globals, the file-static `forward`/`vright`/`muzzle` globals, and `trap_Trace` are needed — how is state threaded in?
/// Raven `WP_FireStunBaton`.
///
/// Source: `oracle/codemp/game/g_weapon.c:3282-3357`
pub fn WP_FireStunBaton(ctx: GameContext<'_>, ent: EntityId, alt_fire: qboolean) {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t = ctx.entity_mut(ent);
    unsafe {
        let mut muzzleStun: vec3_t;

        if (*ent).client.is_null() {
            muzzleStun = (*ent).r.currentOrigin;
            muzzleStun[2] += 8.0;
        } else {
            muzzleStun = (*((*ent).client as *mut gclient_t)).ps.origin;
            muzzleStun[2] += (*((*ent).client as *mut gclient_t)).ps.viewheight as f32 - 6.0;
        }

        let mut tmp = muzzleStun;
        crate::q_math::_VectorMA(tmp, 20.0, (*ctx.world).globals.forward, &mut muzzleStun);
        tmp = muzzleStun;
        crate::q_math::_VectorMA(tmp, 4.0, (*ctx.world).globals.vright, &mut muzzleStun);

        let mut end: vec3_t = [0.0; 3];
        crate::q_math::_VectorMA(
            muzzleStun,
            (STUN_BATON_RANGE) as f32,
            (*ctx.world).globals.forward,
            &mut end,
        );

        let maxs: vec3_t = [6.0, 6.0, 6.0];
        let mut mins: vec3_t = [0.0; 3];
        crate::q_math::_VectorScale(maxs, -1.0, &mut mins);

        let mut tr: trace_t = std::mem::zeroed();
        trap::Trace(
            ctx.engine,
            mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                &mut tr,
                &muzzleStun as *const vec3_t,
                &mins as *const vec3_t,
                &maxs as *const vec3_t,
                &end as *const vec3_t,
                (*ent).s.number,
                MASK_SHOT,
            ),
        );

        if (tr.entityNum as u32) >= (ENTITYNUM_WORLD) as u32 {
            return;
        }

        let tr_ent = &mut (*ctx.world).g_entities[tr.entityNum as usize] as *mut gentity_t;

        if !tr_ent.is_null() && (*tr_ent).takedamage != 0 && !(*tr_ent).client.is_null() {
            // see if either party is involved in a duel
            if (*((*tr_ent).client as *mut gclient_t)).ps.duelInProgress != 0
                && (*((*tr_ent).client as *mut gclient_t)).ps.duelIndex != (*ent).s.number
            {
                return;
            }

            if !(*ent).client.is_null()
                && (*((*ent).client as *mut gclient_t)).ps.duelInProgress != 0
                && (*((*ent).client as *mut gclient_t)).ps.duelIndex != (*tr_ent).s.number
            {
                return;
            }
        }

        if !tr_ent.is_null() && (*tr_ent).takedamage != 0 {
            crate::g_utils::G_PlayEffect((EFFECT_STUNHIT) as i32, tr.endpos, tr.plane.normal);

            crate::g_utils::G_Sound(
                ctx,
                tr_ent,
                CHAN_WEAPON,
                crate::g_utils::G_SoundIndex(
                    cstr(&format!(
                        "sound/weapons/melee/punch{}",
                        (*ctx.world).bg_state.rng.Q_irand(1, 4)
                    ))
                    .as_ptr(),
                ),
            );
            crate::g_combat::G_Damage(
                ctx,
                ctx.entity_id_of(tr_ent),
                ctx.entity_id_of(ent),
                ctx.entity_id_of(ent),
                Some(&mut (*ctx.world).globals.forward),
                tr.endpos,
                STUN_BATON_DAMAGE,
                DAMAGE_NO_KNOCKBACK | DAMAGE_HALF_ABSORB,
                MOD_STUN_BATON as c_int,
            );

            if !(*tr_ent).client.is_null() {
                // if it's a player then use the shock effect
                if (*((*tr_ent).client as *mut gclient_t)).NPC_class == CLASS_VEHICLE {
                    // not on vehicles
                    let pVeh = (*tr_ent).m_pVehicle as *mut mp_bg::vehicles::Vehicle_t;
                    if pVeh.is_null()
                        || (*(*pVeh).m_pVehicleInfo).r#type
                            == mp_bg::vehicles::vehicleType_t::VH_ANIMAL
                        || (*(*pVeh).m_pVehicleInfo).r#type
                            == mp_bg::vehicles::vehicleType_t::VH_FLIER
                    {
                        // can zap animals
                        (*((*tr_ent).client as *mut gclient_t)).ps.electrifyTime =
                            (*ctx.world).level.time + (*ctx.world).bg_state.rng.Q_irand(3000, 4000);
                    }
                } else {
                    (*((*tr_ent).client as *mut gclient_t)).ps.electrifyTime =
                        (*ctx.world).level.time + 700;
                }
            }
        }
    }
}

// PORT-NOTE(seam-threading): faithful skeleton signature carries no &Engine/&mut GameWorld, but `g_entities`, the file-static `forward`/`vright`/`muzzle` globals, and `trap_Trace` are needed — how is state threaded in?
/// Raven `WP_FireMelee`.
///
/// Source: `oracle/codemp/game/g_weapon.c:3363-3445`
pub fn WP_FireMelee(ctx: GameContext<'_>, ent: EntityId, alt_fire: qboolean) {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t = ctx.entity_mut(ent);
    unsafe {
        if !(*ent).client.is_null()
            && (*((*ent).client as *mut gclient_t)).ps.torsoAnim == (BOTH_MELEE2) as i32
        {
            // right
            if (*((*ent).client as *mut gclient_t)).ps.brokenLimbs & (1 << (BROKENLIMB_RARM as i32))
                != 0
            {
                return;
            }
        } else {
            // left
            if (*((*ent).client as *mut gclient_t)).ps.brokenLimbs & (1 << (BROKENLIMB_LARM as i32))
                != 0
            {
                return;
            }
        }

        let mut muzzlePunch: vec3_t;
        if (*ent).client.is_null() {
            muzzlePunch = (*ent).r.currentOrigin;
            muzzlePunch[2] += 8.0;
        } else {
            muzzlePunch = (*((*ent).client as *mut gclient_t)).ps.origin;
            muzzlePunch[2] += (*((*ent).client as *mut gclient_t)).ps.viewheight as f32 - 6.0;
        }

        let mut tmp = muzzlePunch;
        crate::q_math::_VectorMA(tmp, 20.0, (*ctx.world).globals.forward, &mut muzzlePunch);
        tmp = muzzlePunch;
        crate::q_math::_VectorMA(tmp, 4.0, (*ctx.world).globals.vright, &mut muzzlePunch);

        let mut end: vec3_t = [0.0; 3];
        crate::q_math::_VectorMA(
            muzzlePunch,
            (MELEE_RANGE) as f32,
            (*ctx.world).globals.forward,
            &mut end,
        );

        let maxs: vec3_t = [6.0, 6.0, 6.0];
        let mut mins: vec3_t = [0.0; 3];
        crate::q_math::_VectorScale(maxs, -1.0, &mut mins);

        let mut tr: trace_t = std::mem::zeroed();
        trap::Trace(
            ctx.engine,
            mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                &mut tr,
                &muzzlePunch as *const vec3_t,
                &mins as *const vec3_t,
                &maxs as *const vec3_t,
                &end as *const vec3_t,
                (*ent).s.number,
                MASK_SHOT,
            ),
        );

        if tr.entityNum != ENTITYNUM_NONE as i16 {
            // hit something
            let tr_ent = &mut (*ctx.world).g_entities[tr.entityNum as usize] as *mut gentity_t;

            crate::g_utils::G_Sound(
                ctx,
                ent,
                CHAN_AUTO,
                crate::g_utils::G_SoundIndex(
                    cstr(&format!(
                        "sound/weapons/melee/punch{}",
                        (*ctx.world).bg_state.rng.Q_irand(1, 4)
                    ))
                    .as_ptr(),
                ),
            );

            if (*tr_ent).takedamage != 0 && !(*tr_ent).client.is_null() {
                // special duel checks
                if (*((*tr_ent).client as *mut gclient_t)).ps.duelInProgress != 0
                    && (*((*tr_ent).client as *mut gclient_t)).ps.duelIndex != (*ent).s.number
                {
                    return;
                }

                if !(*ent).client.is_null()
                    && (*((*ent).client as *mut gclient_t)).ps.duelInProgress != 0
                    && (*((*ent).client as *mut gclient_t)).ps.duelIndex != (*tr_ent).s.number
                {
                    return;
                }
            }

            if (*tr_ent).takedamage != 0 {
                // damage them, do more damage if we're in the second right hook
                let mut dmg: c_int = MELEE_SWING1_DAMAGE;

                if !(*ent).client.is_null()
                    && (*((*ent).client as *mut gclient_t)).ps.torsoAnim == (BOTH_MELEE2) as i32
                {
                    // do a tad bit more damage on the second swing
                    dmg = MELEE_SWING2_DAMAGE;
                }

                if crate::g_combat::G_HeavyMelee(ctx, ctx.entity_id_of(ent)) != qfalse {
                    // 2x damage for heavy melee class
                    dmg *= 2;
                }

                crate::g_combat::G_Damage(
                    ctx,
                    ctx.entity_id_of(tr_ent),
                    ctx.entity_id_of(ent),
                    ctx.entity_id_of(ent),
                    Some(&mut (*ctx.world).globals.forward),
                    tr.endpos,
                    dmg,
                    DAMAGE_NO_ARMOR,
                    MOD_MELEE as c_int,
                );
            }
        }
    }
}

/// Raven `SnapVectorTowards`.
///
/// Source: `oracle/codemp/game/g_weapon.c:3464-3474`
pub fn SnapVectorTowards(v: vec3_t, to: vec3_t) -> vec3_t {
    let mut v = v;
    for i in 0..3 {
        if to[i] <= v[i] {
            v[i] = v[i] as c_int as f32;
        } else {
            v[i] = v[i] as c_int as f32 + 1.0;
        }
    }
    v
}

/// Raven `LogAccuracyHit`.
///
/// Source: `oracle/codemp/game/g_weapon.c:3485-3516`
pub fn LogAccuracyHit(
    ctx: GameContext<'_>,
    target: EntityId,
    attacker: Option<EntityId>,
) -> qboolean {
    // STAGE-1: EntityId/Option params (body null-checks attacker), raw re-derived
    // verbatim (Stage-2 debt).
    let target: *mut gentity_t = ctx.entity_mut(target);
    let attacker: *mut gentity_t =
        unsafe { crate::ent_id::resolve(ctx.world().g_entities.as_mut_ptr(), attacker) };
    unsafe {
        if (*target).takedamage == 0 {
            return qfalse;
        }

        if target == attacker {
            return qfalse;
        }

        if (*target).client.is_null() {
            return qfalse;
        }

        if attacker.is_null() {
            return qfalse;
        }

        if (*attacker).client.is_null() {
            return qfalse;
        }

        let targetClient = (*target).client as *mut gclient_t;
        if (*targetClient).ps.stats[statIndex_t::STAT_HEALTH as usize] <= 0 {
            return qfalse;
        }

        if crate::g_team::OnSameTeam(ctx, target, attacker) != qfalse {
            return qfalse;
        }

        qtrue
    }
}

/// Raven `CalcMuzzlePoint`.
///
/// Source: `oracle/codemp/game/g_weapon.c:3530-3551`
pub fn CalcMuzzlePoint(
    ctx: GameContext<'_>,
    ent: EntityId,
    forward: vec3_t,
    right: vec3_t,
    up: vec3_t,
    muzzlePoint: &mut vec3_t,
) {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t = ctx.entity_mut(ent);
    unsafe {
        let weapontype: c_int = (*ent).s.weapon;
        *muzzlePoint = (*ent).s.pos.trBase;

        let muzzleOffPoint: vec3_t = WP_MuzzlePoint[weapontype as usize];

        if weapontype > WP_NONE && weapontype < WP_NUM_WEAPONS {
            // Use the table to generate the muzzlepoint;
            // Crouching.  Use the add-to-Z method to adjust vertically.
            let tmp = *muzzlePoint;
            crate::q_math::_VectorMA(tmp, muzzleOffPoint[0], forward, muzzlePoint);
            let tmp = *muzzlePoint;
            crate::q_math::_VectorMA(tmp, muzzleOffPoint[1], right, muzzlePoint);
            muzzlePoint[2] +=
                (*((*ent).client as *mut gclient_t)).ps.viewheight as f32 + muzzleOffPoint[2];
        }

        // snap to integer coordinates for more efficient network bandwidth usage
        trap::SnapVector(
            ctx.engine,
            mp_abi::game::syscalls::G_SNAPVECTOR::GSnapvectorArgs::new(muzzlePoint),
        );
    }
}

/// Raven `CalcMuzzlePointOrigin`.
///
/// Set muzzle location relative to pivoting eye.
///
/// Source: `oracle/codemp/game/g_weapon.c:3560-3566`
pub fn CalcMuzzlePointOrigin(
    ent: &gentity_t,
    origin: vec3_t,
    forward: vec3_t,
    right: vec3_t,
    up: vec3_t,
    muzzlePoint: vec3_t,
) -> vec3_t {
    // STAGE-1: ctx-free leaf &gentity_t borrow (read-only); raw re-derived
    // verbatim (Stage-2 debt).
    let ent: *const gentity_t = ent;
    unsafe {
        let client = (*ent).client as *mut gclient_t;
        let mut muzzlePoint = (*ent).s.pos.trBase;
        muzzlePoint[2] += (*client).ps.viewheight as f32;
        // VectorMA( muzzlePoint, 14, forward, muzzlePoint )
        muzzlePoint[0] += 14.0 * forward[0];
        muzzlePoint[1] += 14.0 * forward[1];
        muzzlePoint[2] += 14.0 * forward[2];
        // Snap to integer coordinates for more efficient network bandwidth
        // usage. Raven's inline `SnapVector` (q_shared.h:1408-1427) truncates
        // via x87 `fistp` (round-to-nearest); `.round()` is the closest safe
        // Rust equivalent.
        for i in 0..3 {
            muzzlePoint[i] = muzzlePoint[i].round();
        }
        muzzlePoint
    }
}

