// PORT-NOTE(seam-threading): faithful skeleton signature carries no &Engine/&mut GameWorld, but `level.time`, `muzzle`, and `trap_Trace` are needed — how is state threaded in?
/// Raven `WP_CalcVehMuzzle`.
///
/// Source: `oracle/codemp/game/g_weapon.c:3580-3608`
pub fn WP_CalcVehMuzzle(ctx: GameContext<'_>, ent: EntityId, muzzleNum: c_int) {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t = ctx.entity_mut(ent);
    unsafe {
        let pVeh = (*ent).m_pVehicle as *mut mp_bg::vehicles::Vehicle_t;
        let mut boltMatrix: mdxaBone_t = std::mem::zeroed();
        let mut vehAngles: vec3_t;

        // Raven `assert(pVeh)`; UB if null — the one defined behavior here is to bail.
        if pVeh.is_null() {
            return;
        }

        if (*pVeh).m_iMuzzleTime[muzzleNum as usize] == (*ctx.world).level.time {
            // already done for this frame, don't need to do it again
            return;
        }
        // Uh... how about we set this, hunh...?  :)
        (*pVeh).m_iMuzzleTime[muzzleNum as usize] = (*ctx.world).level.time;

        vehAngles = (*((*ent).client as *mut gclient_t)).ps.viewangles;
        if !(*pVeh).m_pVehicleInfo.is_null()
            && ((*(*pVeh).m_pVehicleInfo).r#type == mp_bg::vehicles::vehicleType_t::VH_ANIMAL
                || (*(*pVeh).m_pVehicleInfo).r#type == mp_bg::vehicles::vehicleType_t::VH_WALKER
                || (*(*pVeh).m_pVehicleInfo).r#type == mp_bg::vehicles::vehicleType_t::VH_SPEEDER)
        {
            vehAngles[PITCH] = 0.0;
            vehAngles[ROLL] = 0.0;
        }

        trap::G2API_GetBoltMatrix_NoRecNoRot(
            ctx.engine,
            mp_abi::game::syscalls::G_G2_GETBOLT_NOREC_NOROT::GG2GetboltNorecNorotArgs::new(
                (*ent).ghoul2,
                0,
                (*pVeh).m_iMuzzleTag[muzzleNum as usize],
                &mut boltMatrix,
                &vehAngles as *const vec3_t,
                &(*((*ent).client as *mut gclient_t)).ps.origin as *const vec3_t,
                (*ctx.world).level.time,
                core::ptr::null_mut(),
                &(*ent).modelScale as *const vec3_t,
            ),
        );
        use mp_qshared::shared::Eorientations;
        BG_GiveMeVectorFromMatrix(
            &boltMatrix as *const mdxaBone_t,
            Eorientations::ORIGIN as c_int,
            &mut (*pVeh).m_vMuzzlePos[muzzleNum as usize],
        );
        BG_GiveMeVectorFromMatrix(
            &boltMatrix as *const mdxaBone_t,
            Eorientations::NEGATIVE_Y as c_int,
            &mut (*pVeh).m_vMuzzleDir[muzzleNum as usize],
        );
    }
}

// PORT-NOTE(seam-threading): faithful skeleton signature carries no &Engine/&mut GameWorld, but `level.time` is needed — how is state threaded in?
/// Raven `WP_VehWeapSetSolidToOwner`.
///
/// Source: `oracle/codemp/game/g_weapon.c:3610-3625`
pub fn WP_VehWeapSetSolidToOwner(ctx: GameContext<'_>, self_: EntityId) {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let self_: *mut gentity_t = ctx.entity_mut(self_);
    unsafe {
        (*self_).r.svFlags |= SVF_OWNERNOTSHARED;
        if (*self_).genericValue1 != 0 {
            // expire after a time
            if (*self_).genericValue2 != 0 {
                // blow up when your lifetime is up
                (*self_).think = Some(EntThink::G_ExplodeMissile).into(); // FIXME: custom func?
            } else {
                // just remove yourself
                (*self_).think = Some(EntThink::G_FreeEntity).into(); // FIXME: custom func?
            }
            (*self_).nextthink = (*ctx.world).level.time + (*self_).genericValue1;
        }
    }
}

// PORT-NOTE(seam-threading): faithful skeleton signature carries no &Engine/&mut GameWorld, but `level`/`g_entities` globals are needed — how is state threaded in?
/// Raven `WP_FireVehicleWeapon`.
///
/// Source: `oracle/codemp/game/g_weapon.c:3628-3848`
pub fn WP_FireVehicleWeapon(
    ctx: GameContext<'_>,
    ent: EntityId,
    start: vec3_t,
    dir: vec3_t,
    vehWeapon: *mut vehWeaponInfo_t,
    alt_fire: qboolean,
    isTurretWeap: qboolean,
) -> *mut gentity_t {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    // Return stays raw `*mut gentity_t` (return conversion is a later pass);
    // `vehWeapon` is not a gentity handle so it stays raw.
    let ent: *mut gentity_t = ctx.entity_mut(ent);
    unsafe {
        let mut missile: *mut gentity_t = std::ptr::null_mut();

        // FIXME: add some randomness...?  Inherent inaccuracy stat of weapon?  Pilot skill?
        if vehWeapon.is_null() {
            // invalid vehicle weapon
            return std::ptr::null_mut();
        } else if (*vehWeapon).bIsProjectile != qfalse {
            // projectile entity
            let mut start = start;
            let maxs: vec3_t = [
                (*vehWeapon).fWidth / 2.0,
                (*vehWeapon).fWidth / 2.0,
                (*vehWeapon).fHeight / 2.0,
            ];
            let mut mins: vec3_t = [0.0; 3];
            crate::q_math::_VectorScale(maxs, -1.0, &mut mins);

            // make sure our start point isn't on the other side of a wall
            start = W_TraceSetStart(ctx, ctx.entity_id_of(ent).unwrap(), start, mins, maxs);

            // FIXME: CUSTOM MODEL?
            // QUERY: alt_fire true or not?  Does it matter?
            missile = crate::g_missile::CreateMissile(
                ctx,
                start,
                dir,
                (*vehWeapon).fSpeed,
                10000,
                ctx.entity_id_of(ent).unwrap(),
                qfalse,
            );

            (*missile).classname = c"vehicle_proj".as_ptr() as *mut c_char;

            (*missile).s.genericenemyindex = (*ent).s.number + MAX_GENTITIES as c_int;
            (*missile).damage = (*vehWeapon).iDamage;
            (*missile).splashDamage = (*vehWeapon).iSplashDamage;
            (*missile).splashRadius = ((*vehWeapon).fSplashRadius) as i32;

            // FIXME: externalize some of these properties?
            (*missile).dflags = DAMAGE_DEATH_KNOCKBACK;
            (*missile).clipmask = MASK_SHOT;
            // Maybe by checking flags...?
            if (*vehWeapon).bSaberBlockable != qfalse {
                (*missile).clipmask |= CONTENTS_LIGHTSABER;
            }

            // Make it easier to hit things
            (*missile).r.mins = mins;
            (*missile).r.maxs = maxs;
            // some slightly different stuff for things with bboxes
            if (*vehWeapon).fWidth != 0.0 || (*vehWeapon).fHeight != 0.0 {
                // we assume it's a rocket-like thing
                (*missile).s.weapon = WP_ROCKET_LAUNCHER; // does this really matter?
                (*missile).methodOfDeath = MOD_VEHICLE as c_int; // MOD_ROCKET;
                (*missile).splashMethodOfDeath = MOD_VEHICLE as c_int; // MOD_ROCKET;// ?SPLASH;

                // we don't want it to ever bounce
                (*missile).bounceCount = 0;

                (*missile).mass = (10) as f32;
            } else {
                // a blaster-laser-like thing
                (*missile).s.weapon = WP_BLASTER; // does this really matter?
                (*missile).methodOfDeath = MOD_VEHICLE as c_int; // count as a heavy weap
                (*missile).splashMethodOfDeath = MOD_VEHICLE as c_int; // ?SPLASH;
                                                                       // we don't want it to bounce forever
                (*missile).bounceCount = 8;
            }

            if (*vehWeapon).bHasGravity != qfalse {
                // TESTME: is this all we need to do?
                (*missile).s.weapon = WP_THERMAL; // does this really matter?
                (*missile).s.pos.trType = TR_GRAVITY;
            }

            if (*vehWeapon).bIonWeapon != qfalse {
                // so it disables ship shields and sends them out of control
                (*missile).s.weapon = WP_DEMP2;
            }

            if (*vehWeapon).iHealth != 0 {
                // the missile can take damage
                // don't do this - ships hit them first and have no trace.plane.normal to
                // bounce off it at and end up in the middle of the asteroid...
            }

            // pilot should own this projectile on server if we have a pilot
            let pVeh = (*ent).m_pVehicle as *mut mp_bg::vehicles::Vehicle_t;
            if !pVeh.is_null() && !(*pVeh).m_pPilot.is_null() {
                // owned by vehicle pilot
                (*missile).r.ownerNum =
                    ((*((*pVeh).m_pPilot as *mut gentity_t)).s.number as u32) as i32;
            } else {
                // owned by vehicle?
                (*missile).r.ownerNum = ((*ent).s.number as u32) as i32;
            }

            // set veh as cgame side owner for purpose of fx overrides
            (*missile).s.owner = (*ent).s.number;
            if alt_fire != qfalse {
                // use the second weapon's iShotFX
                (*missile).s.eFlags |= EF_ALT_FIRING;
            }
            if isTurretWeap != qfalse {
                // look for the turret weapon info on cgame side, not vehicle weapon info
                (*missile).s.weapon = WP_TURRET;
            }
            if (*vehWeapon).iLifeTime != 0 {
                // expire after a time
                if (*vehWeapon).bExplodeOnExpire != qfalse {
                    // blow up when your lifetime is up
                    (*missile).think = Some(EntThink::G_ExplodeMissile).into(); // FIXME: custom func?
                } else {
                    // just remove yourself
                    (*missile).think = Some(EntThink::G_FreeEntity).into(); // FIXME: custom func?
                }
                (*missile).nextthink = (*ctx.world).level.time + (*vehWeapon).iLifeTime;
            }
            (*missile).s.otherEntityNum2 = vehWeapon
                .offset_from(&(*ctx.world).bg_state.g_vehWeaponInfo[0] as *const vehWeaponInfo_t)
                as c_int;
            (*missile).s.eFlags |= EF_JETPACK_ACTIVE;
            // homing
            if (*vehWeapon).fHoming != 0.0 {
                // homing missile
                if !(*ent).client.is_null()
                    && (*((*ent).client as *mut gclient_t)).ps.rocketLockIndex
                        != ENTITYNUM_NONE as c_int
                {
                    let mut dif: c_int = 0;
                    let mut rTime: f32;
                    rTime = (*((*ent).client as *mut gclient_t)).ps.rocketLockTime as f32;

                    if rTime == -1.0 {
                        rTime = (*((*ent).client as *mut gclient_t)).ps.rocketLastValidTime as f32;
                    }

                    if (*vehWeapon).iLockOnTime == 0 {
                        // no minimum lock-on time
                        dif = 10; // guaranteed lock-on
                    } else {
                        let lockTimeInterval = (*vehWeapon).iLockOnTime as f32 / 16.0;
                        dif =
                            (((*ctx.world).level.time as f32 - rTime) / lockTimeInterval) as c_int;
                    }

                    if dif < 0 {
                        dif = 0;
                    }

                    // It's 10 even though it locks client-side at 8, because we want them to
                    // have a sturdy lock first, and because there's a slight difference in
                    // time between server and client
                    if dif >= 10 && rTime != -1.0 {
                        let enemy = &mut (*ctx.world).g_entities
                            [(*((*ent).client as *mut gclient_t)).ps.rocketLockIndex as usize]
                            as *mut gentity_t;
                        (*missile).enemy =
                            Some(ent_id((*ctx.world).g_entities.as_mut_ptr(), enemy));

                        if !(*enemy).client.is_null()
                            && (*enemy).health > 0
                            && crate::g_team::OnSameTeam(ctx, ent, enemy) == qfalse
                        {
                            // if enemy became invalid, died, or is on the same team, then don't seek it
                            (*missile).spawnflags |= 1; // just to let it know it should be faster...
                            (*missile).speed = (*vehWeapon).fSpeed;
                            (*missile).angle = (*vehWeapon).fHoming;
                            (*missile).radius = (*vehWeapon).fHomingFOV;
                            // crap, if we have a lifetime, need to store that somewhere else on
                            // ent and have rocketThink func check it every frame...
                            if (*vehWeapon).iLifeTime != 0 {
                                // expire after a time
                                (*missile).genericValue1 =
                                    (*ctx.world).level.time + (*vehWeapon).iLifeTime;
                                (*missile).genericValue2 = (*vehWeapon).bExplodeOnExpire as c_int;
                            }
                            // now go ahead and use the rocketThink func
                            (*missile).think = Some(EntThink::rocketThink).into(); // FIXME: custom func?
                            (*missile).nextthink =
                                (*ctx.world).level.time + VEH_HOMING_MISSILE_THINK_TIME;
                            (*missile).s.eFlags |= EF_RADAROBJECT; // FIXME: externalize
                            if (*enemy).s.NPC_class == (CLASS_VEHICLE) as i32 {
                                // let vehicle know we've locked on to them
                                (*missile).s.otherEntityNum = (*enemy).s.number;
                            }
                        }
                    }

                    (*missile).movedir = dir;
                    (*missile).random = 1.0; // FIXME: externalize?
                }
            }
            if (*vehWeapon).fSpeed == 0.0 {
                // a mine or something?
                if (*vehWeapon).iHealth != 0 {
                    // the missile can take damage
                    (*missile).health = (*vehWeapon).iHealth;
                    (*missile).takedamage = qtrue;
                    (*missile).r.contents = MASK_SHOT;
                    (*missile).die = Some(EntDie::RocketDie).into();
                }
                // only do damage when someone touches us
                (*missile).s.weapon = WP_THERMAL; // does this really matter?
                crate::g_utils::G_SetOrigin(missile, start);
                (*missile).touch = Some(EntTouch::WP_TouchVehMissile).into();
                (*missile).s.eFlags |= EF_RADAROBJECT; // FIXME: externalize
                                                       // crap, if we have a lifetime, need to store that somewhere else on ent
                                                       // and have rocketThink func check it every frame...
                if (*vehWeapon).iLifeTime != 0 {
                    // expire after a time
                    (*missile).genericValue1 = (*vehWeapon).iLifeTime;
                    (*missile).genericValue2 = (*vehWeapon).bExplodeOnExpire as c_int;
                }
                // now go ahead and use the setsolidtoowner func
                (*missile).think = Some(EntThink::WP_VehWeapSetSolidToOwner).into();
                (*missile).nextthink = (*ctx.world).level.time + 3000;
            }
        } else {
            // traceline
            // FIXME: implement
        }

        missile
    }
}

// PORT-NOTE(bg-dep): `gentity_t.m_pVehicle` is a stale `*mut c_void` placeholder (its doc comment predates `Vehicle_t` landing in `mp_bg`) — is the cast to `*mut Vehicle_t` sanctioned yet, or does the gentity_t field need updating first? Also `EV_VEH_FIRE` (`entity_event_t`) needs qualifying but is otherwise resolvable.
/// Raven `G_VehMuzzleFireFX`.
///
/// Source: `oracle/codemp/game/g_weapon.c:3851-3881`
pub fn G_VehMuzzleFireFX(
    ctx: GameContext<'_>,
    ent: EntityId,
    broadcaster: Option<EntityId>,
    muzzlesFired: c_int,
) {
    // STAGE-1: EntityId/Option params (body null-checks broadcaster), raw
    // re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t = ctx.entity_mut(ent);
    let broadcaster: *mut gentity_t =
        unsafe { crate::ent_id::resolve(ctx.world().g_entities.as_mut_ptr(), broadcaster) };
    unsafe {
        let pVeh = (*ent).m_pVehicle as *mut mp_bg::vehicles::Vehicle_t;

        if pVeh.is_null() {
            return;
        }

        let b: *mut gentity_t;
        if broadcaster.is_null() {
            // oh well. We will WASTE A TEMPENT.
            b = crate::g_utils::G_TempEntity(
                ctx,
                (*((*ent).client as *mut gclient_t)).ps.origin,
                EV_VEH_FIRE as c_int,
            );
        } else {
            // joy
            b = broadcaster;
        }

        // this guy owns it
        (*b).s.owner = (*ent).s.number;

        // this is the bitfield of all muzzles fired this time
        // NOTE: just need MAX_VEHICLE_MUZZLES bits for this... should be cool
        // since it's currently 12 and we're sending it in 16 bits
        (*b).s.trickedentindex = muzzlesFired;

        if !broadcaster.is_null() {
            // add the event
            crate::g_utils::G_AddEvent(b, EV_VEH_FIRE as c_int, 0);
        }
    }
}

// PORT-NOTE(seam-threading): faithful skeleton signature carries no &Engine/&mut GameWorld, but `trap_Trace` is needed — how is state threaded in?
/// Raven `G_EstimateCamPos`.
///
/// Source: `oracle/codemp/game/g_weapon.c:3883-3959`
pub fn G_EstimateCamPos(
    ctx: GameContext<'_>,
    viewAngles: vec3_t,
    // Read AND written (Raven bumps the caller's buffer by viewheight at
    // g_weapon.c:3918) — `&mut` per the settled vec3 out-param rule.
    cameraFocusLoc: &mut vec3_t,
    viewheight: f32,
    thirdPersonRange: f32,
    thirdPersonHorzOffset: f32,
    vertOffset: f32,
    pitchOffset: f32,
    ignoreEntNum: c_int,
    camPos: &mut vec3_t,
) {
    unsafe {
        // `MASK_SOLID`/`CONTENTS_PLAYERCLIP` come from the prelude's `surface_flags`
        // re-export. Raven: `int MASK_CAMERACLIP = (MASK_SOLID|CONTENTS_PLAYERCLIP);`
        let MASK_CAMERACLIP: c_int = MASK_SOLID | CONTENTS_PLAYERCLIP;
        let CAMERA_SIZE: f32 = 4.0;
        let cameramins: vec3_t = [-CAMERA_SIZE, -CAMERA_SIZE, -CAMERA_SIZE];
        let cameramaxs: vec3_t = [CAMERA_SIZE, CAMERA_SIZE, CAMERA_SIZE];

        let mut cameraFocusAngles = viewAngles;
        cameraFocusAngles[PITCH] += pitchOffset;
        if (*ctx.world).cvars.bg_fighterAltControl.integer == 0 {
            // clamp view pitch
            cameraFocusAngles[PITCH] = crate::q_math::AngleNormalize180(cameraFocusAngles[PITCH]);
            if cameraFocusAngles[PITCH] > 80.0 {
                cameraFocusAngles[PITCH] = 80.0;
            } else if cameraFocusAngles[PITCH] < -80.0 {
                cameraFocusAngles[PITCH] = -80.0;
            }
        }
        let mut camerafwd: vec3_t = [0.0; 3];
        let mut cameraup: vec3_t = [0.0; 3];
        crate::q_math::AngleVectors(
            cameraFocusAngles,
            Some(&mut camerafwd),
            None,
            Some(&mut cameraup),
        );

        cameraFocusLoc[2] += viewheight;

        let mut cameraIdealTarget = *cameraFocusLoc;
        cameraIdealTarget[2] += vertOffset;

        // NOTE: on cgame, this uses the thirdpersontargetdamp value, we ignore that here
        let mut cameraCurTarget = cameraIdealTarget;
        let mut trace: trace_t = std::mem::zeroed();
        trap::Trace(
            ctx.engine,
            mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                &mut trace,
                &*cameraFocusLoc as *const vec3_t,
                &cameramins as *const vec3_t,
                &cameramaxs as *const vec3_t,
                &cameraCurTarget as *const vec3_t,
                ignoreEntNum,
                MASK_CAMERACLIP,
            ),
        );
        if trace.fraction < 1.0 {
            cameraCurTarget = trace.endpos;
        }

        let mut cameraIdealLoc: vec3_t = [0.0; 3];
        crate::q_math::_VectorMA(
            cameraIdealTarget,
            -thirdPersonRange,
            camerafwd,
            &mut cameraIdealLoc,
        );
        // NOTE: on cgame, this uses the thirdpersoncameradamp value, we ignore that here
        let mut cameraCurLoc = cameraIdealLoc;
        trap::Trace(
            ctx.engine,
            mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                &mut trace,
                &cameraCurTarget as *const vec3_t,
                &cameramins as *const vec3_t,
                &cameramaxs as *const vec3_t,
                &cameraCurLoc as *const vec3_t,
                ignoreEntNum,
                MASK_CAMERACLIP,
            ),
        );
        if trace.fraction < 1.0 {
            cameraCurLoc = trace.endpos;
        }

        let mut diff: vec3_t = [0.0; 3];
        crate::q_math::_VectorSubtract(cameraCurTarget, cameraCurLoc, &mut diff);
        {
            let dist = crate::q_math::VectorNormalize(&mut diff);
            // under normal circumstances, should never be 0.00000 and so on.
            if dist == 0.0 || diff[0] == 0.0 || diff[1] == 0.0 {
                // must be hitting something, need some value to calc angles, so use cam forward
                diff = camerafwd;
            }
        }

        let mut camAngles: vec3_t = [0.0; 3];
        crate::q_math::vectoangles(diff, &mut camAngles);

        if thirdPersonHorzOffset != 0.0 {
            let mut viewaxis: [vec3_t; 3] = [[0.0; 3]; 3];
            crate::q_math::AnglesToAxis(camAngles, viewaxis.as_mut_ptr());
            let tmp = cameraCurLoc;
            crate::q_math::_VectorMA(tmp, thirdPersonHorzOffset, viewaxis[1], &mut cameraCurLoc);
        }

        // PORT-NOTE(out-param-vec3): `camPos` is a vec3_t out-param per the
        // settled vec3 rule (docs/porting/rosetta.md: outputs are `&mut`);
        // Raven copies `cameraCurLoc` back through it.
        *camPos = cameraCurLoc;
    }
}

// PORT-NOTE(parked-dep): depends on G_EstimateCamPos (parked: seam-threading) and MAX_STRAFE_TIME (not ported)
/// Raven `WP_GetVehicleCamPos`.
///
/// Source: `oracle/codemp/game/g_weapon.c:3961-4020`
pub fn WP_GetVehicleCamPos(
    ctx: GameContext<'_>,
    ent: EntityId,
    pilot: EntityId,
    camPos: &mut [f32; 3],
) {
    // STAGE-1: EntityId params, raw body re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t = ctx.entity_mut(ent);
    let pilot: *mut gentity_t = ctx.entity_mut(pilot);
    // PORT-NOTE(unported-type): `vehicleInfo_t` (`Vehicle_t::m_pVehicleInfo`)
    // isn't ported yet; fields referenced through it exactly as the oracle
    // cites them, reported as missing symbols.
    unsafe {
        let pVeh = (*ent).m_pVehicle as *mut mp_bg::vehicles::Vehicle_t;
        let vehInfo = (*pVeh).m_pVehicleInfo as *mut mp_bg::vehicles::vehicleInfo_t;
        let mut thirdPersonHorzOffset: f32 = (*vehInfo).cameraHorzOffset;
        let mut thirdPersonRange: f32 = (*vehInfo).cameraRange;
        let mut pitchOffset: f32 = (*vehInfo).cameraPitchOffset;
        let mut vertOffset: f32 = (*vehInfo).cameraVertOffset;

        if (*((*ent).client as *mut gclient_t)).ps.hackingTime != 0 {
            thirdPersonHorzOffset += ((*((*ent).client as *mut gclient_t)).ps.hackingTime as f32
                / MAX_STRAFE_TIME)
                * -80.0;
            thirdPersonRange += ((*((*ent).client as *mut gclient_t)).ps.hackingTime as f32
                / MAX_STRAFE_TIME)
                .abs()
                * 100.0;
        }

        if (*vehInfo).cameraPitchDependantVertOffset != qfalse {
            if (*((*pilot).client as *mut gclient_t)).ps.viewangles[PITCH] > 0.0 {
                vertOffset =
                    130.0 + (*((*pilot).client as *mut gclient_t)).ps.viewangles[PITCH] * -10.0;
                if vertOffset < -170.0 {
                    vertOffset = -170.0;
                }
            } else if (*((*pilot).client as *mut gclient_t)).ps.viewangles[PITCH] < 0.0 {
                vertOffset =
                    130.0 + (*((*pilot).client as *mut gclient_t)).ps.viewangles[PITCH] * -5.0;
                if vertOffset > 130.0 {
                    vertOffset = 130.0;
                }
            } else {
                vertOffset = 30.0;
            }
            if (*((*pilot).client as *mut gclient_t)).ps.viewangles[PITCH] > 0.0 {
                pitchOffset = (*((*pilot).client as *mut gclient_t)).ps.viewangles[PITCH] * -0.75;
            } else if (*((*pilot).client as *mut gclient_t)).ps.viewangles[PITCH] < 0.0 {
                pitchOffset = (*((*pilot).client as *mut gclient_t)).ps.viewangles[PITCH] * -0.75;
            } else {
                pitchOffset = 0.0;
            }
        }

        // Control Scheme 3 Method:
        // Raven passes `pilot->client->ps.origin` directly, so the viewheight
        // bump inside G_EstimateCamPos lands in the pilot's ps.origin buffer.
        G_EstimateCamPos(
            ctx,
            (*((*ent).client as *mut gclient_t)).ps.viewangles,
            &mut (*((*pilot).client as *mut gclient_t)).ps.origin,
            (*((*pilot).client as *mut gclient_t)).ps.viewheight as f32,
            thirdPersonRange,
            thirdPersonHorzOffset,
            vertOffset,
            pitchOffset,
            (*pilot).s.number,
            camPos,
        );
    }
}

/// Raven `WP_VehLeadCrosshairVeh`.
///
/// Source: `oracle/codemp/game/g_weapon.c:4022-4047`
pub fn WP_VehLeadCrosshairVeh(
    ctx: GameContext<'_>,
    camTraceEnt: Option<EntityId>,
    newEnd: &mut [f32; 3],
    dir: [f32; 3],
    shotStart: [f32; 3],
    shotDir: &mut [f32; 3],
) {
    // STAGE-1: Option param (body null-checks camTraceEnt), raw re-derived
    // verbatim (Stage-2 debt).
    let camTraceEnt: *mut gentity_t =
        unsafe { crate::ent_id::resolve(ctx.world().g_entities.as_mut_ptr(), camTraceEnt) };
    unsafe {
        if (*ctx.world).cvars.g_vehAutoAimLead.integer != 0 {
            if !camTraceEnt.is_null()
                && !(*camTraceEnt).client.is_null()
                && (*((*camTraceEnt).client as *mut gclient_t)).NPC_class == CLASS_VEHICLE
            {
                let dot = crate::q_math::_DotProduct(
                    (*((*camTraceEnt).client as *mut gclient_t)).ps.velocity,
                    dir,
                );
                let distAdjust = dot;
                let mut predPos = [0.0f32; 3];
                let mut predShotDir = [0.0f32; 3];

                if distAdjust > 500.0f32
                    || crate::q_math::DistanceSquared(
                        (*((*camTraceEnt).client as *mut gclient_t)).ps.origin,
                        shotStart,
                    ) > 7000000.0f32
                {
                    crate::q_math::_VectorMA(*newEnd, distAdjust, dir, &mut predPos);
                    crate::q_math::_VectorSubtract(predPos, shotStart, &mut predShotDir);
                    crate::q_math::VectorNormalize(&mut predShotDir);
                    let dot = crate::q_math::_DotProduct(predShotDir, *shotDir);
                    if dot >= 0.75f32 {
                        crate::q_math::_VectorCopy(predPos, newEnd);
                    }
                }
            }
        }
        crate::q_math::_VectorSubtract(*newEnd, shotStart, shotDir);
        crate::q_math::VectorNormalize(shotDir);
    }
}

// PORT-NOTE(parked-dep): depends on BG_VehTraceFromCamPos (parked)
/// Raven `WP_VehCheckTraceFromCamPos`.
///
/// Source: `oracle/codemp/game/g_weapon.c:4052-4113`
pub fn WP_VehCheckTraceFromCamPos(
    ctx: GameContext<'_>,
    ent: Option<EntityId>,
    shotStart: [f32; 3],
    shotDir: &mut [f32; 3],
) -> qboolean {
    // STAGE-1: Option param (body null-checks ent), raw re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t =
        unsafe { crate::ent_id::resolve(ctx.world().g_entities.as_mut_ptr(), ent) };
    unsafe {
        let mut shotDir = shotDir;
        // FIXME: only if dynamicCrosshair and dynamicCrosshairPrecision is on!
        if ent.is_null() || (*ent).m_pVehicle.is_null() {
            return qfalse;
        }
        let pVeh = (*ent).m_pVehicle as *mut mp_bg::vehicles::Vehicle_t;
        if (*pVeh).m_pVehicleInfo.is_null() || (*pVeh).m_pPilot.is_null() {
            return qfalse;
        }
        let pilot = (*pVeh).m_pPilot as *mut gentity_t;
        if (*pilot).client.is_null() || (*pilot).s.number >= MAX_CLIENTS as c_int {
            // not being driven / being driven, but not by a real client, no need to worry about crosshair
            return qfalse;
        }

        let vehInfo = (*pVeh).m_pVehicleInfo as *mut mp_bg::vehicles::vehicleInfo_t;
        if ((*vehInfo).r#type == mp_bg::vehicles::vehicleType_t::VH_FIGHTER
            && (*ctx.world).globals.g_cullDistance > MAX_XHAIR_DIST_ACCURACY)
            || (*vehInfo).r#type == mp_bg::vehicles::vehicleType_t::VH_WALKER
        {
            // FIRST: simulate the normal crosshair trace from the center of the veh straight forward
            let mut trace: trace_t = std::mem::zeroed();
            let mut dir: vec3_t = [0.0; 3];
            let mut start: vec3_t;
            let mut end: vec3_t = [0.0; 3];
            if (*vehInfo).r#type == mp_bg::vehicles::vehicleType_t::VH_WALKER {
                // for some reason, the walker always draws the crosshair out from the first muzzle point
                crate::q_math::AngleVectors(
                    (*((*ent).client as *mut gclient_t)).ps.viewangles,
                    Some(&mut dir),
                    None,
                    None,
                );
                start = (*ent).r.currentOrigin;
                start[2] += (*vehInfo).height - DEFAULT_MINS_2 - 48.0;
            } else {
                let mut ang: vec3_t = [0.0; 3];
                if (*vehInfo).r#type == mp_bg::vehicles::vehicleType_t::VH_SPEEDER {
                    ang = [0.0, *(*pVeh).m_vOrientation.add(1), 0.0];
                } else {
                    ang = [
                        *(*pVeh).m_vOrientation.add(0),
                        *(*pVeh).m_vOrientation.add(1),
                        *(*pVeh).m_vOrientation.add(2),
                    ];
                }
                crate::q_math::AngleVectors(ang, Some(&mut dir), None, None);
                start = (*ent).r.currentOrigin;
            }
            crate::q_math::_VectorMA(start, (*ctx.world).globals.g_cullDistance, dir, &mut end);
            trap::Trace(
                ctx.engine,
                mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                    &mut trace,
                    &start as *const vec3_t,
                    &[0.0f32, 0.0f32, 0.0f32] as *const vec3_t,
                    &[0.0f32, 0.0f32, 0.0f32] as *const vec3_t,
                    &end as *const vec3_t,
                    (*ent).s.number,
                    CONTENTS_SOLID | CONTENTS_BODY,
                ),
            );

            if (*vehInfo).r#type == mp_bg::vehicles::vehicleType_t::VH_WALKER {
                // just use the result of that one trace since walkers don't do the extra trace
                crate::q_math::_VectorSubtract(trace.endpos, shotStart, shotDir);
                crate::q_math::VectorNormalize(shotDir);
                return qtrue;
            } else {
                // NOW do the trace from the camPos and compare with above trace
                let mut extraTrace: trace_t = std::mem::zeroed();
                let mut newEnd: vec3_t = [0.0; 3];
                // `BG_VehTraceFromCamPos` is a bg-tier free fn (`&BgState`/
                // `&dyn BgTraps`); its `WP_GetVehicleCamPos` upcall needs game
                // state, so it also takes `&mut dyn GameCallbacks`. This
                // game-tier caller builds both adapters from `ctx`.
                let camTraceEntNum = crate::bg_pmove::BG_VehTraceFromCamPos(
                    &mut extraTrace,
                    ent as *mut bgEntity_t,
                    (*ent).r.currentOrigin,
                    shotStart,
                    end,
                    &mut newEnd,
                    &mut *shotDir,
                    trace.fraction * (*ctx.world).globals.g_cullDistance,
                    &(*ctx.world).bg_state,
                    &crate::bg_channel::GameBgTraps::new(ctx.engine),
                    &mut crate::bg_channel::GameCallbacksImpl {
                        world: ctx.world,
                        engine: ctx.engine,
                    },
                );
                if camTraceEntNum != 0 {
                    let camTraceEnt = &mut (*ctx.world).g_entities[(camTraceEntNum - 1) as usize]
                        as *mut gentity_t;
                    WP_VehLeadCrosshairVeh(
                        ctx,
                        ctx.entity_id_of(camTraceEnt),
                        &mut newEnd,
                        dir,
                        shotStart,
                        shotDir,
                    );
                    return qtrue;
                }
            }
        }
        qfalse
    }
}

/// Raven `FireVehicleWeapon`.
///
/// Source: `oracle/codemp/game/g_weapon.c:4116-4413`
pub fn FireVehicleWeapon(ctx: GameContext<'_>, ent: EntityId, alt_fire: qboolean) {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t = ctx.entity_mut(ent);
    unsafe {
        let pVeh = (*ent).m_pVehicle as *mut mp_bg::vehicles::Vehicle_t;
        if pVeh.is_null() {
            return;
        }

        let pVeh = &mut *pVeh;

        if pVeh.m_iRemovedSurfaces != 0 {
            return;
        }

        if pVeh.m_pVehicleInfo.as_ref().unwrap().r#type == VH_WALKER
            && (*((*ent).client as *mut gclient_t)).ps.electrifyTime > (*ctx.world).level.time
        {
            return;
        }

        if !pVeh.m_pVehicleInfo.is_null()
            && (pVeh.m_pVehicleInfo.as_ref().unwrap().r#type != VH_FIGHTER
                || (pVeh.m_ulFlags & (VEH_WINGSOPEN as u64)) != 0)
        {
            let mut weaponNum: c_int = 0;
            let mut vehWeaponIndex = VEH_WEAPON_NONE;
            let mut delay: c_int = 1000;
            let mut aimCorrect = qfalse;
            let mut linkedFiring = qfalse;

            if alt_fire == 0 {
                weaponNum = 0;
            } else {
                weaponNum = 1;
            }

            vehWeaponIndex = pVeh.m_pVehicleInfo.as_ref().unwrap().weapon[weaponNum as usize].ID;

            if pVeh.weaponStatus[weaponNum as usize].ammo <= 0 {
                if !pVeh.m_pPilot.is_null() && (*pVeh.m_pPilot).s.number < MAX_CLIENTS as c_int {
                    let mut i = 0;
                    while i < MAX_VEHICLE_MUZZLES as c_int {
                        if pVeh.m_pVehicleInfo.as_ref().unwrap().weapMuzzle[i as usize]
                            != vehWeaponIndex
                        {
                            i += 1;
                            continue;
                        }
                        if pVeh.m_iMuzzleTag[i as usize] != -1
                            && pVeh.m_iMuzzleWait[i as usize] < (*ctx.world).level.time
                        {
                            G_AddEvent(
                                pVeh.m_pPilot as *mut gentity_t,
                                (EV_NOAMMO) as i32,
                                weaponNum,
                            );
                            break;
                        }
                        i += 1;
                    }
                }
                return;
            }

            delay = pVeh.m_pVehicleInfo.as_ref().unwrap().weapon[weaponNum as usize].delay;
            aimCorrect = pVeh.m_pVehicleInfo.as_ref().unwrap().weapon[weaponNum as usize].aimCorrect
                as qboolean;
            if pVeh.m_pVehicleInfo.as_ref().unwrap().weapon[weaponNum as usize].linkable == 2
                || (pVeh.m_pVehicleInfo.as_ref().unwrap().weapon[weaponNum as usize].linkable == 1
                    && pVeh.weaponStatus[weaponNum as usize].linked != 0)
            {
                linkedFiring = qtrue;
            }

            if vehWeaponIndex <= VEH_WEAPON_BASE || vehWeaponIndex >= MAX_VEH_WEAPONS as c_int {
                return;
            }

            let mut numMuzzles: c_int = 0;
            let mut numMuzzlesReady: c_int = 0;
            let mut cumulativeDelay: c_int = 0;
            let mut cumulativeAmmo: c_int = 0;
            let mut sentAmmoWarning = qfalse;

            let vehWeapon: *mut vehWeaponInfo_t =
                &mut (*ctx.world).bg_state.g_vehWeaponInfo[vehWeaponIndex as usize];

            if pVeh.m_pVehicleInfo.as_ref().unwrap().weapon[weaponNum as usize].linkable == 2 {
                cumulativeDelay = delay;
            }

            let mut i = 0;
            while i < MAX_VEHICLE_MUZZLES as c_int {
                if pVeh.m_pVehicleInfo.as_ref().unwrap().weapMuzzle[i as usize] != vehWeaponIndex {
                    i += 1;
                    continue;
                }
                if pVeh.m_iMuzzleTag[i as usize] != -1
                    && pVeh.m_iMuzzleWait[i as usize] < (*ctx.world).level.time
                {
                    numMuzzlesReady += 1;
                }
                if pVeh.m_pVehicleInfo.as_ref().unwrap().weapMuzzle
                    [pVeh.weaponStatus[weaponNum as usize].nextMuzzle as usize]
                    != vehWeaponIndex
                {
                    pVeh.weaponStatus[weaponNum as usize].nextMuzzle = i;
                }
                if linkedFiring != 0 {
                    cumulativeAmmo += (*vehWeapon).iAmmoPerShot;
                    if pVeh.m_pVehicleInfo.as_ref().unwrap().weapon[weaponNum as usize].linkable
                        != 2
                    {
                        cumulativeDelay += delay;
                    }
                }
                numMuzzles += 1;
                i += 1;
            }

            if linkedFiring != 0 {
                if numMuzzlesReady != numMuzzles {
                    return;
                } else if pVeh.weaponStatus[weaponNum as usize].ammo < cumulativeAmmo {
                    if !pVeh.m_pPilot.is_null() && (*pVeh.m_pPilot).s.number < MAX_CLIENTS as c_int
                    {
                        G_AddEvent(
                            pVeh.m_pPilot as *mut gentity_t,
                            (EV_NOAMMO) as i32,
                            weaponNum,
                        );
                    }
                    return;
                }
            }

            let mut muzzlesFired: c_int = 0;
            let mut missile: *mut gentity_t = std::ptr::null_mut();
            let mut clearRocketLockEntity = qfalse;

            'try_fire: {
                let mut i = 0;
                while i < MAX_VEHICLE_MUZZLES as c_int {
                    if pVeh.m_pVehicleInfo.as_ref().unwrap().weapMuzzle[i as usize]
                        != vehWeaponIndex
                    {
                        i += 1;
                        continue;
                    }
                    if linkedFiring == 0 && i != pVeh.weaponStatus[weaponNum as usize].nextMuzzle {
                        i += 1;
                        continue;
                    }

                    if pVeh.m_iMuzzleTag[i as usize] != -1
                        && pVeh.m_iMuzzleWait[i as usize] < (*ctx.world).level.time
                    {
                        if pVeh.weaponStatus[weaponNum as usize].ammo < (*vehWeapon).iAmmoPerShot {
                            if sentAmmoWarning == 0 {
                                sentAmmoWarning = qtrue;
                                if !pVeh.m_pPilot.is_null()
                                    && (*pVeh.m_pPilot).s.number < MAX_CLIENTS as c_int
                                {
                                    G_AddEvent(
                                        pVeh.m_pPilot as *mut gentity_t,
                                        (EV_NOAMMO) as i32,
                                        weaponNum,
                                    );
                                }
                            }
                        } else {
                            WP_CalcVehMuzzle(ctx, ctx.entity_id_of(ent).unwrap(), i);
                            let mut start = pVeh.m_vMuzzlePos[i as usize];
                            let mut dir = pVeh.m_vMuzzleDir[i as usize];
                            if WP_VehCheckTraceFromCamPos(
                                ctx,
                                ctx.entity_id_of(ent),
                                start,
                                &mut dir,
                            ) != 0
                            {
                            } else if aimCorrect != 0 {
                                let mut trace: trace_t = std::mem::zeroed();
                                let mut end = [0.0f32; 3];
                                let mut ang = [0.0f32; 3];
                                let mut fixedDir = [0.0f32; 3];

                                if pVeh.m_pVehicleInfo.as_ref().unwrap().r#type == VH_SPEEDER {
                                    crate::q_math::VectorSet(
                                        &mut ang,
                                        0.0f32,
                                        *pVeh.m_vOrientation.add(1),
                                        0.0f32,
                                    );
                                } else {
                                    crate::q_math::_VectorCopy(
                                        *(pVeh.m_vOrientation as *const vec3_t),
                                        &mut ang,
                                    );
                                }
                                crate::q_math::AngleVectors(ang, Some(&mut fixedDir), None, None);
                                crate::q_math::_VectorMA(
                                    (*ent).r.currentOrigin,
                                    32768.0f32,
                                    fixedDir,
                                    &mut end,
                                );
                                trap::Trace(
                                    ctx.engine,
                                    mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                                        &mut trace,
                                        &(*ent).r.currentOrigin as *const vec3_t,
                                        &vec3_origin as *const vec3_t,
                                        &vec3_origin as *const vec3_t,
                                        &end as *const vec3_t,
                                        (*ent).s.number,
                                        MASK_SHOT,
                                    ),
                                );
                                if trace.fraction < 1.0f32
                                    && trace.allsolid == 0
                                    && trace.startsolid == 0
                                {
                                    let mut newEnd = [0.0f32; 3];
                                    crate::q_math::_VectorCopy(trace.endpos, &mut newEnd);
                                    WP_VehLeadCrosshairVeh(
                                        ctx,
                                        EntityId::from_num(trace.entityNum as c_int),
                                        &mut newEnd,
                                        fixedDir,
                                        start,
                                        &mut dir,
                                    );
                                }
                            }

                            muzzlesFired |= 1 << i;

                            missile = WP_FireVehicleWeapon(
                                ctx,
                                ctx.entity_id_of(ent).unwrap(),
                                start,
                                dir,
                                vehWeapon as *mut _,
                                alt_fire,
                                qfalse,
                            );
                            if (*vehWeapon).fHoming != (0) as f32 {
                                clearRocketLockEntity = qtrue;
                            }
                        }

                        if linkedFiring != 0 {
                            i += 1;
                            continue;
                        }

                        if numMuzzles > 1 {
                            let mut nextMuzzle = pVeh.weaponStatus[weaponNum as usize].nextMuzzle;
                            loop {
                                nextMuzzle += 1;
                                if nextMuzzle >= MAX_VEHICLE_MUZZLES as c_int {
                                    nextMuzzle = 0;
                                }
                                if nextMuzzle == pVeh.weaponStatus[weaponNum as usize].nextMuzzle {
                                    break;
                                }
                                if pVeh.m_pVehicleInfo.as_ref().unwrap().weapMuzzle
                                    [nextMuzzle as usize]
                                    == vehWeaponIndex
                                {
                                    pVeh.weaponStatus[weaponNum as usize].nextMuzzle = nextMuzzle;
                                    break;
                                }
                            }
                        }

                        pVeh.m_iMuzzleWait
                            [pVeh.weaponStatus[weaponNum as usize].nextMuzzle as usize] =
                            (*ctx.world).level.time + delay;
                        pVeh.weaponStatus[weaponNum as usize].ammo -= (*vehWeapon).iAmmoPerShot;
                        if !pVeh.m_pParentEntity.is_null()
                            && !(pVeh.m_pParentEntity as *mut gentity_t).is_null()
                            && !(*(pVeh.m_pParentEntity as *mut gentity_t)).client.is_null()
                        {
                            (*((*(pVeh.m_pParentEntity as *mut gentity_t)).client
                                as *mut gclient_t))
                                .ps
                                .ammo[weaponNum as usize] =
                                pVeh.weaponStatus[weaponNum as usize].ammo;
                        }
                        // Oracle `goto tryFire;` — after firing one muzzle in the
                        // non-linked case, bail out of the muzzle loop entirely
                        // (skipping the cumulative ammo/delay pass) so only one
                        // muzzle fires per frame, round-robin.
                        break 'try_fire;
                    }
                    i += 1;
                }

                if cumulativeAmmo != 0 {
                    pVeh.weaponStatus[weaponNum as usize].ammo -= cumulativeAmmo;
                    if !pVeh.m_pParentEntity.is_null()
                        && !(pVeh.m_pParentEntity as *mut gentity_t).is_null()
                        && !(*(pVeh.m_pParentEntity as *mut gentity_t)).client.is_null()
                    {
                        (*((*(pVeh.m_pParentEntity as *mut gentity_t)).client as *mut gclient_t))
                            .ps
                            .ammo[weaponNum as usize] = pVeh.weaponStatus[weaponNum as usize].ammo;
                    }
                }
                if cumulativeDelay != 0 {
                    let mut i = 0;
                    while i < MAX_VEHICLE_MUZZLES as c_int {
                        if pVeh.m_pVehicleInfo.as_ref().unwrap().weapMuzzle[i as usize]
                            != vehWeaponIndex
                        {
                            i += 1;
                            continue;
                        }
                        pVeh.m_iMuzzleWait[i as usize] = (*ctx.world).level.time + cumulativeDelay;
                        i += 1;
                    }
                }
            } // 'try_fire (oracle `tryFire:` label)

            if clearRocketLockEntity != 0 {
                (*((*ent).client as *mut gclient_t)).ps.rocketLockIndex = ENTITYNUM_NONE as c_int;
                (*((*ent).client as *mut gclient_t)).ps.rocketLockTime = (0) as f32;
                (*((*ent).client as *mut gclient_t)).ps.rocketTargetTime = (0) as f32;
            }

            if !vehWeapon.is_null() && muzzlesFired > 0 {
                G_VehMuzzleFireFX(
                    ctx,
                    ctx.entity_id_of(ent).unwrap(),
                    ctx.entity_id_of(missile),
                    muzzlesFired,
                );
            }
        }
    }
}

/// Raven `FireWeapon`.
///
/// Source: `oracle/codemp/game/g_weapon.c:4424-4608`
pub fn FireWeapon(ctx: GameContext<'_>, ent: Option<EntityId>, altFire: qboolean) {
    // STAGE-1: Option param (body null-checks ent), raw re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t =
        unsafe { crate::ent_id::resolve(ctx.world().g_entities.as_mut_ptr(), ent) };
    unsafe {
        if (*((*ent).client as *mut gclient_t)).ps.powerups[PW_QUAD as usize] != 0 {
            (*ctx.world).globals.s_quadFactor = (*ctx.world).cvars.g_quadfactor.value;
        } else {
            (*ctx.world).globals.s_quadFactor = 1.0f32;
        }

        if (*ent).s.weapon != WP_SABER
            && (*ent).s.weapon != WP_STUN_BATON
            && (*ent).s.weapon != WP_MELEE
        {
            if (*ent).s.weapon == WP_FLECHETTE {
                (*((*ent).client as *mut gclient_t)).accuracy_shots += FLECHETTE_SHOTS;
            } else {
                (*((*ent).client as *mut gclient_t)).accuracy_shots += 1;
            }
        }

        if !ent.is_null()
            && !(*ent).client.is_null()
            && (*((*ent).client as *mut gclient_t)).NPC_class == CLASS_VEHICLE
        {
            FireVehicleWeapon(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            return;
        }

        // Raven's file statics `forward, vright, up` / `muzzle` (g_weapon.c:13-14)
        // are `GameGlobals` fields here; seed them exactly where the oracle seeds
        // its statics so the WP_Fire* readers below observe them.
        // Source: `oracle/codemp/game/g_weapon.c:4448-4512`

        if (*ent).s.weapon == WP_EMPLACED_GUN
            && (*((*ent).client as *mut gclient_t)).ps.emplacedIndex != 0
        {
            let emp = &mut (*ctx.world).g_entities
                [(*((*ent).client as *mut gclient_t)).ps.emplacedIndex as usize]
                as *mut gentity_t;

            if (*emp).inuse != 0 {
                let mut yaw = 0.0f32;
                let mut viewAngCap = [0.0f32; 3];
                let mut override_val = 0;

                crate::q_math::_VectorCopy(
                    (*((*ent).client as *mut gclient_t)).ps.viewangles,
                    &mut viewAngCap,
                );
                if viewAngCap[0] > 40.0f32 {
                    viewAngCap[0] = 40.0f32;
                }

                override_val = BG_EmplacedView(
                    (*((*ent).client as *mut gclient_t)).ps.viewangles,
                    (*emp).s.angles,
                    &mut yaw,
                    (*emp).s.origin2[0],
                );

                if override_val != 0 {
                    viewAngCap[1] = yaw;
                }

                crate::q_math::AngleVectors(
                    viewAngCap,
                    Some(&mut (*ctx.world).globals.forward),
                    Some(&mut (*ctx.world).globals.vright),
                    Some(&mut (*ctx.world).globals.up),
                );
            } else {
                crate::q_math::AngleVectors(
                    (*((*ent).client as *mut gclient_t)).ps.viewangles,
                    Some(&mut (*ctx.world).globals.forward),
                    Some(&mut (*ctx.world).globals.vright),
                    Some(&mut (*ctx.world).globals.up),
                );
            }
        } else if (*ent).s.number < MAX_CLIENTS as c_int
            && (*((*ent).client as *mut gclient_t)).ps.m_iVehicleNum != 0
            && (*ent).s.weapon == WP_BLASTER
        {
            let mut vehTurnAngles = [0.0f32; 3];
            let vehEnt = &mut (*ctx.world).g_entities
                [(*((*ent).client as *mut gclient_t)).ps.m_iVehicleNum as usize]
                as *mut gentity_t;

            if (*vehEnt).inuse != 0
                && !(*vehEnt).client.is_null()
                && !(*vehEnt).m_pVehicle.is_null()
            {
                crate::q_math::_VectorCopy(
                    *((*((*vehEnt).m_pVehicle as *mut mp_bg::vehicles::Vehicle_t)).m_vOrientation
                        as *const vec3_t),
                    &mut vehTurnAngles,
                );
                vehTurnAngles[0] = (*((*ent).client as *mut gclient_t)).ps.viewangles[0];
            } else {
                crate::q_math::_VectorCopy(
                    (*((*ent).client as *mut gclient_t)).ps.viewangles,
                    &mut vehTurnAngles,
                );
            }
            if (*((*ent).client as *mut gclient_t)).pers.cmd.rightmove > 0 {
                vehTurnAngles[1] -= 90.0f32;
            } else if (*((*ent).client as *mut gclient_t)).pers.cmd.rightmove < 0 {
                vehTurnAngles[1] += 90.0f32;
            }

            crate::q_math::AngleVectors(
                vehTurnAngles,
                Some(&mut (*ctx.world).globals.forward),
                Some(&mut (*ctx.world).globals.vright),
                Some(&mut (*ctx.world).globals.up),
            );
        } else {
            crate::q_math::AngleVectors(
                (*((*ent).client as *mut gclient_t)).ps.viewangles,
                Some(&mut (*ctx.world).globals.forward),
                Some(&mut (*ctx.world).globals.vright),
                Some(&mut (*ctx.world).globals.up),
            );
        }

        CalcMuzzlePoint(
            ctx,
            ctx.entity_id_of(ent).unwrap(),
            (*ctx.world).globals.forward,
            (*ctx.world).globals.vright,
            (*ctx.world).globals.up,
            &mut (*ctx.world).globals.muzzle,
        );

        match (*ent).s.weapon {
            WP_STUN_BATON => {
                WP_FireStunBaton(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            }
            WP_MELEE => {
                WP_FireMelee(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            }
            WP_SABER => {}
            WP_BRYAR_PISTOL => {
                WP_FireBryarPistol(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            }
            WP_CONCUSSION => {
                if altFire != 0 {
                    WP_FireConcussionAlt(ctx, ctx.entity_id_of(ent).unwrap());
                } else {
                    WP_FireConcussion(ctx, ctx.entity_id_of(ent).unwrap());
                }
            }
            WP_BRYAR_OLD => {
                WP_FireBryarPistol(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            }
            WP_BLASTER => {
                WP_FireBlaster(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            }
            WP_DISRUPTOR => {
                WP_FireDisruptor(ctx, ctx.entity_id_of(ent), altFire);
            }
            WP_BOWCASTER => {
                WP_FireBowcaster(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            }
            WP_REPEATER => {
                WP_FireRepeater(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            }
            WP_DEMP2 => {
                WP_FireDEMP2(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            }
            WP_FLECHETTE => {
                WP_FireFlechette(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            }
            WP_ROCKET_LAUNCHER => {
                WP_FireRocket(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            }
            WP_THERMAL => {
                WP_FireThermalDetonator(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            }
            WP_TRIP_MINE => {
                WP_PlaceLaserTrap(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
            }
            WP_DET_PACK => {
                WP_DropDetPack(ctx, ctx.entity_id_of(ent), altFire);
            }
            WP_EMPLACED_GUN => {
                if !(*ent).client.is_null() && (*((*ent).client as *mut gclient_t)).ewebIndex != 0 {
                } else {
                    WP_FireEmplaced(ctx, ctx.entity_id_of(ent).unwrap(), altFire);
                }
            }
            _ => {}
        }
    }

    unsafe { G_LogWeaponFire(ctx, (*ent).s.number, (*ent).s.weapon) };
}

/// Raven `WP_FireEmplaced`.
///
/// Source: `oracle/codemp/game/g_weapon.c:4611-4660`
pub fn WP_FireEmplaced(ctx: GameContext<'_>, ent: EntityId, altFire: qboolean) {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t = ctx.entity_mut(ent);
    unsafe {
        if (*ent).client.is_null() {
            return;
        }

        if (*((*ent).client as *mut gclient_t)).ps.emplacedIndex == 0 {
            return;
        }

        let gun = &mut (*ctx.world).g_entities
            [(*((*ent).client as *mut gclient_t)).ps.emplacedIndex as usize]
            as *mut gentity_t;

        if (*gun).inuse == 0 || (*gun).health <= 0 {
            return;
        }

        let mut gunpoint = (*gun).s.origin;
        gunpoint[2] += 46.0f32;

        let mut right = [0.0f32; 3];
        crate::q_math::AngleVectors(
            (*((*ent).client as *mut gclient_t)).ps.viewangles,
            None,
            Some(&mut right),
            None,
        );

        let mut side = 0;
        if (*gun).genericValue10 != 0 {
            crate::q_math::_VectorMA(gunpoint, 10.0f32, right, &mut gunpoint);
            side = 0;
        } else {
            crate::q_math::_VectorMA(gunpoint, -10.0f32, right, &mut gunpoint);
            side = 1;
        }

        (*gun).genericValue10 = side;
        G_AddEvent(gun, (EV_FIRE_WEAPON) as i32, side);

        let mut angs = [0.0f32; 3];
        let mut dir = [0.0f32; 3];
        // Oracle uses the file-static `forward` (set by FireWeapon from the
        // capped/yaw-overridden emplaced view angles), not a fresh
        // AngleVectors of the raw viewangles — matching the sibling fire fns.
        crate::q_math::vectoangles((*ctx.world).globals.forward, &mut angs);
        crate::q_math::AngleVectors(angs, Some(&mut dir), None, None);

        WP_FireEmplacedMissile(
            ctx,
            ctx.entity_id_of(gun).unwrap(),
            gunpoint,
            dir,
            altFire,
            ctx.entity_id_of(ent),
        );
    }
}

/// Raven `emplaced_gun_use`.
///
/// Source: `oracle/codemp/game/g_weapon.c:4691-4802`
pub fn emplaced_gun_use(
    ctx: GameContext<'_>,
    self_: EntityId,
    other: Option<EntityId>,
    trace: *mut trace_t,
) {
    // STAGE-1: EntityId/Option params, raw body re-derived verbatim (Stage-2 debt).
    let self_: *mut gentity_t = ctx.entity_mut(self_);
    let other: *mut gentity_t =
        unsafe { crate::ent_id::resolve(ctx.world().g_entities.as_mut_ptr(), other) };
    unsafe {
        if (*self_).health <= 0 {
            return;
        }

        if !(*self_).activator.is_none() {
            return;
        }

        let activator = other;

        if (*activator).client.is_null() {
            return;
        }

        if (*((*activator).client as *mut gclient_t)).ps.emplacedTime
            > ((*ctx.world).level.time) as f32
        {
            return;
        }

        if (*((*activator).client as *mut gclient_t))
            .ps
            .forceHandExtend
            != (HANDEXTEND_NONE) as i32
        {
            return;
        }

        let zoffset = 50.0f32;
        if (*((*activator).client as *mut gclient_t)).ps.origin[2]
            > (*self_).s.origin[2] + zoffset - 8.0f32
        {
            return;
        }

        if ((*((*activator).client as *mut gclient_t)).ps.pm_flags & PMF_DUCKED) != 0 {
            return;
        }

        if (*((*activator).client as *mut gclient_t)).ps.isJediMaster != 0 {
            return;
        }

        let mut vLen = [0.0f32; 3];
        crate::q_math::_VectorSubtract(
            (*self_).s.origin,
            (*((*activator).client as *mut gclient_t)).ps.origin,
            &mut vLen,
        );
        let ownLen = crate::q_math::VectorLength(vLen);

        if ownLen > 64.0f32 {
            return;
        }

        let mut fwd1 = [0.0f32; 3];
        let mut fwd2 = [0.0f32; 3];
        crate::q_math::AngleVectors(
            (*((*activator).client as *mut gclient_t)).ps.viewangles,
            Some(&mut fwd1),
            None,
            None,
        );
        crate::q_math::AngleVectors((*self_).pos1, Some(&mut fwd2), None, None);

        let mut dot = crate::q_math::_DotProduct(fwd1, fwd2);

        if dot < -0.2f32 {
            TryHeal(ctx, activator, self_);
            return;
        }

        crate::q_math::_VectorSubtract(
            (*self_).s.origin,
            (*((*activator).client as *mut gclient_t)).ps.origin,
            &mut fwd1,
        );
        crate::q_math::VectorNormalize(&mut fwd1);

        dot = crate::q_math::_DotProduct(fwd1, fwd2);

        if dot < 0.6f32 {
            TryHeal(ctx, activator, self_);
            return;
        }

        (*self_).genericValue1 = 1;

        let oldWeapon = (*activator).s.weapon;

        (*((*activator).client as *mut gclient_t)).ps.weapon = (*self_).s.weapon;
        (*((*activator).client as *mut gclient_t)).ps.weaponstate = (WEAPON_READY) as i32;
        (*((*activator).client as *mut gclient_t)).ps.stats[STAT_WEAPONS as usize] |=
            (1 << WP_EMPLACED_GUN);

        (*((*activator).client as *mut gclient_t)).ps.emplacedIndex = (*self_).s.number;

        (*self_).s.emplacedOwner = (*activator).s.number;
        (*self_).s.activeForcePass = (NUM_FORCE_POWERS + 1) as i32;

        (*self_).s.weapon = oldWeapon;

        (*activator).r.ownerNum = (*self_).s.number;
        (*self_).activator = Some(ent_id((*ctx.world).g_entities.as_mut_ptr(), activator));

        let mut anglesToOwner = [0.0f32; 3];
        crate::q_math::_VectorSubtract(
            (*self_).r.currentOrigin,
            (*((*activator).client as *mut gclient_t)).ps.origin,
            &mut anglesToOwner,
        );
        crate::q_math::vectoangles(anglesToOwner, &mut anglesToOwner);
    }
}

/// Raven `emplaced_gun_realuse`.
///
/// Source: `oracle/codemp/game/g_weapon.c:4804-4807`
pub fn emplaced_gun_realuse(
    ctx: GameContext<'_>,
    self_: EntityId,
    other: Option<EntityId>,
    activator: Option<EntityId>,
) {
    // STAGE-1: EntityId/Option params (activator unused by body).
    emplaced_gun_use(ctx, self_, other, std::ptr::null_mut());
}

/// Raven `emplaced_gun_pain`.
///
/// Source: `oracle/codemp/game/g_weapon.c:4810-4823`
pub fn emplaced_gun_pain(
    ctx: GameContext<'_>,
    self_: EntityId,
    attacker: Option<EntityId>,
    damage: c_int,
) {
    // STAGE-1: EntityId/Option params (attacker unused by body), raw self_
    // re-derived verbatim (Stage-2 debt).
    let self_: *mut gentity_t = ctx.entity_mut(self_);
    unsafe {
        (*self_).s.health = (*self_).health;

        if (*self_).health <= 0 {
            // death effect.. for now taken care of on cgame
        } else {
            // if we have a pain behavior set then use it I guess
            crate::NPC_utils::G_ActivateBehavior(ctx, self_, bSet_t::BSET_PAIN as c_int);
        }
    }
}

/// Raven `emplaced_gun_update`.
///
/// Source: `oracle/codemp/game/g_weapon.c:4828-4927`
pub fn emplaced_gun_update(ctx: GameContext<'_>, self_: EntityId) {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let self_: *mut gentity_t = ctx.entity_mut(self_);
    unsafe {
        if (*self_).health < 1 && (*self_).genericValue5 == 0 {
            if ((*self_).spawnflags & (EMPLACED_CANRESPAWN as u32) as i32) != 0 {
                (*self_).genericValue5 = (*ctx.world).level.time + 4000 + (*self_).count;
            }
        } else if (*self_).health < 1 && (*self_).genericValue5 < (*ctx.world).level.time {
            (*self_).s.time = 0;
            (*self_).genericValue4 = 0;
            (*self_).genericValue3 = 0;
            (*self_).health = (EMPLACED_GUN_HEALTH as f32 * 0.4f32) as c_int;
            (*self_).s.health = (*self_).health;
        }

        if (*self_).genericValue4 != 0
            && (*self_).genericValue4 < 2
            && (*self_).s.time < (*ctx.world).level.time
        {
            let mut puffAngle = [0.0f32; 3];
            let mut explOrg = [0.0f32; 3];

            crate::q_math::VectorSet(&mut puffAngle, 0.0f32, 0.0f32, 1.0f32);

            crate::q_math::_VectorCopy((*self_).r.currentOrigin, &mut explOrg);
            explOrg[2] += 16.0f32;

            G_PlayEffect((EFFECT_EXPLOSION_DETPACK) as i32, explOrg, puffAngle);

            (*self_).genericValue3 =
                (*ctx.world).level.time + (*ctx.world).bg_state.rng.Q_irand(2500, 3500);

            G_RadiusDamage(
                ctx,
                (*self_).r.currentOrigin,
                ctx.entity_id_of(self_),
                (*self_).splashDamage as f32,
                (*self_).splashRadius as f32,
                ctx.entity_id_of(self_),
                ctx.entity_id_of(std::ptr::null_mut()),
                MOD_UNKNOWN as c_int,
            );

            (*self_).s.time = -1;

            (*self_).genericValue4 = 2;
        }

        if (*self_).genericValue3 > (*ctx.world).level.time {
            if (*self_).genericValue2 < (*ctx.world).level.time {
                let mut puffAngle = [0.0f32; 3];
                let mut smokeOrg = [0.0f32; 3];

                crate::q_math::VectorSet(&mut puffAngle, 0.0f32, 0.0f32, 1.0f32);
                crate::q_math::_VectorCopy((*self_).r.currentOrigin, &mut smokeOrg);

                smokeOrg[2] += 60.0f32;

                G_PlayEffect((EFFECT_SMOKE) as i32, smokeOrg, puffAngle);
                (*self_).genericValue2 =
                    (*ctx.world).level.time + (*ctx.world).bg_state.rng.Q_irand(250, 400);
            }
        }

        let activator = match (*self_).activator {
            Some(id) => &mut (*ctx.world).g_entities[id.index()] as *mut gentity_t,
            None => core::ptr::null_mut(),
        };

        let mut ownLen = 0.0f32;
        if !(*self_).activator.is_none()
            && !(*activator).client.is_null()
            && (*activator).inuse != 0
        {
            let mut vLen = [0.0f32; 3];
            crate::q_math::_VectorSubtract(
                (*self_).s.origin,
                (*((*activator).client as *mut gclient_t)).ps.origin,
                &mut vLen,
            );
            ownLen = crate::q_math::VectorLength(vLen);

            if ((*((*activator).client as *mut gclient_t)).pers.cmd.buttons & BUTTON_USE) == 0
                && (*self_).genericValue1 != 0
            {
                (*self_).genericValue1 = 0;
            }

            if (((*((*activator).client as *mut gclient_t)).pers.cmd.buttons & BUTTON_USE) != 0)
                && (*self_).genericValue1 == 0
            {
                (*((*activator).client as *mut gclient_t)).ps.emplacedIndex = 0;
                (*((*activator).client as *mut gclient_t)).ps.saberHolstered = 0;
                (*self_).nextthink = (*ctx.world).level.time + 50;
                return;
            }
        }

        if (!(*self_).activator.is_none() && !(*activator).client.is_null())
            && ((*activator).inuse == 0
                || (*((*activator).client as *mut gclient_t)).ps.emplacedIndex != (*self_).s.number
                || (*self_).genericValue4 != 0
                || ownLen > 64.0f32)
        {
            (*((*activator).client as *mut gclient_t)).ps.stats[STAT_WEAPONS as usize] &=
                !(1 << WP_EMPLACED_GUN);

            let oldWeap = (*((*activator).client as *mut gclient_t)).ps.weapon;
            (*((*activator).client as *mut gclient_t)).ps.weapon = (*self_).s.weapon;
            (*self_).s.weapon = oldWeap;
            (*((*activator).client as *mut gclient_t)).ps.emplacedTime =
                ((*ctx.world).level.time + 1000) as f32;
            (*((*activator).client as *mut gclient_t)).ps.emplacedIndex = 0;
            (*((*activator).client as *mut gclient_t)).ps.saberHolstered = 0;
            (*activator).r.ownerNum = (ENTITYNUM_NONE as u32) as i32;
            (*self_).activator = None;

            (*self_).s.activeForcePass = 0;
        } else if !(*self_).activator.is_none() && !(*activator).client.is_null() {
            (*((*activator).client as *mut gclient_t)).ps.weapon = WP_EMPLACED_GUN;
            (*((*activator).client as *mut gclient_t)).ps.weaponstate = (WEAPON_READY) as i32;
        }
        (*self_).nextthink = (*ctx.world).level.time + 50;

        // Note: ownLen was declared earlier but only used in certain conditions
        let ownLen = 0.0f32;
    }
}

/// Raven `emplaced_gun_die`.
///
/// Source: `oracle/codemp/game/g_weapon.c:4930-4942`
pub fn emplaced_gun_die(
    ctx: GameContext<'_>,
    self_: EntityId,
    inflictor: Option<EntityId>,
    attacker: Option<EntityId>,
    damage: c_int,
    r#mod: c_int,
) {
    // STAGE-1: EntityId/Option params (inflictor/attacker unused by body), raw
    // self_ re-derived verbatim (Stage-2 debt).
    let self_: *mut gentity_t = ctx.entity_mut(self_);
    unsafe {
        if (*self_).genericValue4 != 0 {
            return;
        }

        (*self_).genericValue4 = 1;

        (*self_).s.time = (*ctx.world).level.time + 3000;

        (*self_).genericValue5 = 0;
    }
}

/// Raven `SP_emplaced_gun`.
///
/// Source: `oracle/codemp/game/g_weapon.c:4944-5027`
pub fn SP_emplaced_gun(ctx: GameContext<'_>, ent: EntityId) {
    // STAGE-1: EntityId param, raw body re-derived verbatim (Stage-2 debt).
    let ent: *mut gentity_t = ctx.entity_mut(ent);
    unsafe {
        let name = c"models/map_objects/mp/turret_chair.glm";

        let item = BG_FindItemForWeapon(WP_EMPLACED_GUN);
        if !item.is_null() {
            RegisterItem(ctx, item);
        }

        (*ent).r.contents = CONTENTS_SOLID;
        (*ent).s.solid = mp_qshared::common::mp::botlib::solid_t::solid_t::SOLID_BBOX as c_int;

        (*ent).genericValue5 = 0;

        crate::q_math::VectorSet(&mut (*ent).r.mins, -30.0f32, -20.0f32, 8.0f32);
        crate::q_math::VectorSet(&mut (*ent).r.maxs, 30.0f32, 20.0f32, 60.0f32);

        let mut down = (*ent).s.origin;
        down[2] -= 1024.0f32;

        let mut tr: trace_t = std::mem::zeroed();
        trap::Trace(
            ctx.engine,
            mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                &mut tr,
                &(*ent).s.origin as *const vec3_t,
                &(*ent).r.mins as *const vec3_t,
                &(*ent).r.maxs as *const vec3_t,
                &down as *const vec3_t,
                (*ent).s.number,
                MASK_SOLID,
            ),
        );

        if tr.fraction != 1.0f32 && tr.allsolid == 0 && tr.startsolid == 0 {
            crate::q_math::_VectorCopy(tr.endpos, &mut (*ent).s.origin);
        }

        (*ent).spawnflags |= 4; // deadsolid

        (*ent).health = EMPLACED_GUN_HEALTH as c_int;

        if ((*ent).spawnflags & (EMPLACED_CANRESPAWN as u32) as i32) != 0 {
            (*ent).health = ((*ent).health as f32 * 0.4f32) as c_int;
        }

        (*ent).maxHealth = (*ent).health;
        G_ScaleNetHealth(ent);

        (*ent).genericValue4 = 0;

        (*ent).takedamage = qtrue;
        (*ent).pain = Some(EntPain::emplaced_gun_pain).into();
        (*ent).die = Some(EntDie::emplaced_gun_die).into();

        (*ent).splashDamage = 80;
        (*ent).splashRadius = 128;

        G_SpawnInt(
            ctx,
            c"count".as_ptr() as *const c_char,
            c"600".as_ptr() as *const c_char,
            &mut (*ent).count,
        );

        G_SpawnFloat(
            ctx,
            c"constraint".as_ptr() as *const c_char,
            c"60".as_ptr() as *const c_char,
            &mut (*ent).s.origin2[0],
        );

        (*ent).s.modelindex = G_ModelIndex(name.as_ptr());
        (*ent).s.modelGhoul2 = 1;
        (*ent).s.g2radius = 110;

        (*ent).s.weapon = WP_EMPLACED_GUN;

        G_SetOrigin(ent, (*ent).s.origin);

        crate::q_math::_VectorCopy((*ent).s.angles, &mut (*ent).pos1);
        crate::q_math::_VectorCopy((*ent).s.angles, &mut (*ent).r.currentAngles);
        crate::q_math::_VectorCopy((*ent).s.angles, &mut (*ent).s.apos.trBase);

        (*ent).think = Some(EntThink::emplaced_gun_update).into();
        (*ent).nextthink = (*ctx.world).level.time + 50;

        (*ent).use_ = Some(EntUse::emplaced_gun_realuse).into();

        (*ent).r.svFlags |= (SVF_PLAYER_USABLE as u32) as i32;

        (*ent).s.pos.trType = TR_STATIONARY;

        (*ent).s.owner = ((MAX_CLIENTS + 1) as u32) as i32;
        (*ent).s.shouldtarget = qtrue;

        trap::LinkEntity(
            ctx.engine,
            mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(ent),
        );
    }
}
